DO $stage$
DECLARE j jsonb := $payload$[{"language":"es","slug":"arbol-hojaldre-pesto-queso","public_path":"/arbol-hojaldre-pesto-queso","title":"Árbol de hojaldre con pesto y queso para Navidad","excerpt":"Dos láminas de hojaldre guardan una capa de pesto y queso. Los cortes laterales se retuercen para crear las ramas de un árbol navideño que se comparte con las manos.","summary":"Dos láminas de hojaldre guardan una capa de pesto y queso. Los cortes laterales se retuercen para crear las ramas de un árbol navideño que se comparte con las manos.","notes":"Mantén el hojaldre frío y usa pesto espeso para que no se salga. Conserva un eje central sin cortar. Hornea también los recortes y sírvelos: están incluidos en el rendimiento y la nutrición. El huevo se usa para pincelar y se calcula entero, aunque pueda sobrar. Contiene trigo, leche, huevo y los frutos secos que lleve el pesto. Refrigera las sobras dentro de 2 horas, hasta 2 días, y recalienta en horno. La forma y el tiempo final dependen del hojaldre y del horno.","content_html":"<p>Dos láminas de hojaldre guardan una capa de pesto y queso. Los cortes laterales se retuercen para crear las ramas de un árbol navideño que se comparte con las manos.</p><p>Mantén el hojaldre frío y usa pesto espeso para que no se salga. Conserva un eje central sin cortar. Hornea también los recortes y sírvelos: están incluidos en el rendimiento y la nutrición. El huevo se usa para pincelar y se calcula entero, aunque pueda sobrar. Contiene trigo, leche, huevo y los frutos secos que lleve el pesto. Refrigera las sobras dentro de 2 horas, hasta 2 días, y recalienta en horno. La forma y el tiempo final dependen del hojaldre y del horno.</p>","ingredients":[{"name":"hojaldre refrigerado rectangular, dos láminas de unos 25 × 35 cm","amount":"500","unit":"g"},{"name":"pesto de albahaca espeso","amount":"80","unit":"g"},{"name":"mozzarella de baja humedad rallada","amount":"100","unit":"g"},{"name":"parmesano rallado","amount":"25","unit":"g"},{"name":"huevo batido para pincelar","amount":"50","unit":"g"}],"steps":[{"title":"Prepara el hojaldre","content":"Precalienta el horno a 200 °C, calor arriba y abajo. Coloca una lámina de hojaldre de unos 25 × 35 cm sobre papel de horno en una bandeja.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Prepara el hojaldre"},{"title":"Extiende el relleno","content":"Unta 80 g de pesto en una capa fina sobre la lámina, dejando 1 cm de borde. Reparte 100 g de mozzarella y 25 g de parmesano.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Extiende el relleno"},{"title":"Cubre y enfría","content":"Coloca la segunda lámina encima y presiona suavemente. Refrigera 15 minutos para cortar la masa fría.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Cubre y enfría"},{"title":"Recorta el árbol","content":"Corta un triángulo alto con un pequeño tronco en la base. Reserva todos los recortes para hornearlos junto al árbol, en otra bandeja si hace falta.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Recorta el árbol"},{"title":"Marca las ramas","content":"Haz cortes horizontales a ambos lados cada 2 cm, dejando intacta una franja central de unos 3 cm. No cortes el tronco.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Marca las ramas"},{"title":"Retuerce y pincela","content":"Gira cada tira lateral una o dos veces, sin arrancarla del centro. Pincela la superficie con huevo batido; pincela también los recortes.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Retuerce y pincela"},{"title":"Hornea hasta dorar","content":"Hornea 20–25 minutos hasta que el hojaldre esté bien levantado, dorado y cocido en la base. Los recortes pequeños pueden estar antes: retíralos cuando se doren.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Hornea hasta dorar"},{"title":"Sirve para compartir","content":"Deja reposar 5 minutos fuera del horno y pasa el árbol a una tabla. Sirve tibio con todos los recortes horneados para repartirlo entre 8 personas.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Árbol de hojaldre con pesto y queso para Navidad: Sirve para compartir"}],"category":"Entrantes y aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Árbol de hojaldre con pesto y queso para Navidad"}],"video_urls":[],"keywords":["Árbol de hojaldre con pesto y queso para Navidad","hojaldre refrigerado rectangular, dos láminas de unos 25 × 35 cm","pesto de albahaca espeso","mozzarella de baja humedad rallada"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 del árbol y de todos los recortes horneados","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g × peso de cada ingrediente / 100, dividida por las porciones.","note":"Estimación de la formulación; cambia según marcas, porción real y pérdidas de cocción. No es un análisis de laboratorio."},"seo":{"title":"Árbol de hojaldre con pesto y queso para Navidad | Manual de Cocina","description":"Dos láminas de hojaldre guardan una capa de pesto y queso. Los cortes laterales se retuercen para crear las ramas de un árbol navideño que se comparte con las manos.","image_alt":"Árbol de hojaldre con pesto y queso para Navidad","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"¿Puedo formarlo antes de la cena?","a":"Sí: guárdalo formado y sin hornear, bien tapado, en la nevera hasta 12 horas. Pincela y hornea al servir."},{"q":"¿Por qué se enfría antes de cortarlo?","a":"El hojaldre frío conserva mejor sus capas y permite retorcer las ramas sin deformarlas."},{"q":"¿Qué hago con los recortes?","a":"Hornéalos como bocaditos. No se descartan: las cantidades y la nutrición incluyen toda la masa y el relleno."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"blaetterteig-weihnachtsbaum-pesto-kaese","public_path":"/de/blaetterteig-weihnachtsbaum-pesto-kaese","title":"Blätterteig-Weihnachtsbaum mit Pesto und Käse","excerpt":"Zwischen zwei Blätterteigplatten liegen Basilikumpesto, Mozzarella und Parmesan. Gedrehte Seitenstreifen bilden die Zweige dieses Weihnachtsgebäcks zum Teilen.","summary":"Zwischen zwei Blätterteigplatten liegen Basilikumpesto, Mozzarella und Parmesan. Gedrehte Seitenstreifen bilden die Zweige dieses Weihnachtsgebäcks zum Teilen.","notes":"Blätterteig kalt halten, dickes Pesto verwenden und den Mittelsteg nicht durchschneiden. Alle Abschnitte mitbacken und servieren: Menge und Nährwerte schließen sie ein. Das ganze Ei zum Bestreichen wird mitgerechnet, auch wenn etwas übrig bleibt. Enthält Weizen, Milch, Ei und gegebenenfalls Nüsse im Pesto. Reste innerhalb von 2 Stunden kühlen, bis zu 2 Tage aufbewahren und im Ofen erwärmen.","content_html":"<p>Zwischen zwei Blätterteigplatten liegen Basilikumpesto, Mozzarella und Parmesan. Gedrehte Seitenstreifen bilden die Zweige dieses Weihnachtsgebäcks zum Teilen.</p><p>Blätterteig kalt halten, dickes Pesto verwenden und den Mittelsteg nicht durchschneiden. Alle Abschnitte mitbacken und servieren: Menge und Nährwerte schließen sie ein. Das ganze Ei zum Bestreichen wird mitgerechnet, auch wenn etwas übrig bleibt. Enthält Weizen, Milch, Ei und gegebenenfalls Nüsse im Pesto. Reste innerhalb von 2 Stunden kühlen, bis zu 2 Tage aufbewahren und im Ofen erwärmen.</p>","ingredients":[{"name":"gekühlter rechteckiger Blätterteig, zwei Platten von etwa 25 × 35 cm","amount":"500","unit":"g"},{"name":"dickes Basilikumpesto","amount":"80","unit":"g"},{"name":"geriebener schnittfester Mozzarella","amount":"100","unit":"g"},{"name":"geriebener Parmesan","amount":"25","unit":"g"},{"name":"verquirltes Ei zum Bestreichen","amount":"50","unit":"g"}],"steps":[{"title":"Teig vorbereiten","content":"Ofen auf 200 °C Ober-/Unterhitze vorheizen. Eine etwa 25 × 35 cm große Teigplatte auf Backpapier auf ein Blech legen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Teig vorbereiten"},{"title":"Füllung verteilen","content":"80 g Pesto dünn verstreichen, dabei 1 cm Rand lassen. Mit 100 g Mozzarella und 25 g Parmesan bestreuen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Füllung verteilen"},{"title":"Abdecken und kühlen","content":"Zweite Teigplatte auflegen und leicht andrücken. Vor dem Schneiden 15 Minuten kühlen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Abdecken und kühlen"},{"title":"Baum ausschneiden","content":"Ein hohes Dreieck mit kleinem Stamm unten ausschneiden. Alle Abschnitte zum Mitbacken aufbewahren, bei Bedarf auf einem zweiten Blech.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Baum ausschneiden"},{"title":"Zweige einschneiden","content":"Beide Seiten alle 2 cm waagerecht einschneiden. Einen etwa 3 cm breiten Mittelsteg und den Stamm unversehrt lassen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Zweige einschneiden"},{"title":"Drehen und bestreichen","content":"Jeden Seitenstreifen ein- bis zweimal drehen, ohne ihn abzureißen. Baum und Abschnitte mit Ei bestreichen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Drehen und bestreichen"},{"title":"Goldbraun backen","content":"20–25 Minuten backen, bis der Teig aufgegangen, goldbraun und auch unten durchgebacken ist. Kleine Abschnitte gegebenenfalls früher herausnehmen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Goldbraun backen"},{"title":"Gemeinsam genießen","content":"5 Minuten ruhen lassen und auf ein Brett setzen. Lauwarm samt sämtlichen Abschnitten auf acht Personen verteilen.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse: Gemeinsam genießen"}],"category":"Vorspeisen","course":"Vorspeise","cuisine":"International","difficulty":"Einfach","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse"}],"video_urls":[],"keywords":["Blätterteig-Weihnachtsbaum mit Pesto und Käse","gekühlter rechteckiger Blätterteig, zwei Platten von etwa 25 × 35 cm","dickes Basilikumpesto","geriebener schnittfester Mozzarella"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 des Baums samt gebackenen Abschnitten","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Summe der Nährwerte je 100 g × Zutatengewicht / 100, geteilt durch die Portionenzahl.","note":"Schätzung aus der Rezeptur; Marke, tatsächliche Portion und Garverluste verändern die Werte. Keine Laboranalyse."},"seo":{"title":"Blätterteig-Weihnachtsbaum mit Pesto und Käse | Manual de Cocina","description":"Zwischen zwei Blätterteigplatten liegen Basilikumpesto, Mozzarella und Parmesan. Gedrehte Seitenstreifen bilden die Zweige dieses Weihnachtsgebäcks zum Teilen.","image_alt":"Blätterteig-Weihnachtsbaum mit Pesto und Käse","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"Kann ich den Baum vorher formen?","a":"Ja. Ungebacken abgedeckt bis zu 12 Stunden kühlen. Erst vor dem Backen mit Ei bestreichen."},{"q":"Warum wird der Teig gekühlt?","a":"Kalter Blätterteig hält seine Schichten und lässt sich leichter zu Zweigen drehen."},{"q":"Was mache ich mit den Abschnitten?","a":"Als kleine Snacks mitbacken. Die Nährwerte berücksichtigen den gesamten Teig und die gesamte Füllung."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"pesto-cheese-puff-pastry-christmas-tree","public_path":"/en/pesto-cheese-puff-pastry-christmas-tree","title":"Pesto and cheese puff pastry Christmas tree","excerpt":"Two sheets of puff pastry enclose basil pesto, mozzarella and Parmesan. Twist the side strips into branches for a warm Christmas centrepiece to share.","summary":"Two sheets of puff pastry enclose basil pesto, mozzarella and Parmesan. Twist the side strips into branches for a warm Christmas centrepiece to share.","notes":"Keep the pastry cold and use thick pesto. Leave the centre spine intact. Bake and serve every offcut: the yield and nutrition include all the pastry and filling. The calculation includes a whole brushing egg even if some is left. Contains wheat, milk, egg and any nuts in the pesto. Refrigerate leftovers within 2 hours, keep up to 2 days and reheat in the oven.","content_html":"<p>Two sheets of puff pastry enclose basil pesto, mozzarella and Parmesan. Twist the side strips into branches for a warm Christmas centrepiece to share.</p><p>Keep the pastry cold and use thick pesto. Leave the centre spine intact. Bake and serve every offcut: the yield and nutrition include all the pastry and filling. The calculation includes a whole brushing egg even if some is left. Contains wheat, milk, egg and any nuts in the pesto. Refrigerate leftovers within 2 hours, keep up to 2 days and reheat in the oven.</p>","ingredients":[{"name":"chilled rectangular puff pastry, two sheets about 25 × 35 cm","amount":"500","unit":"g"},{"name":"thick basil pesto","amount":"80","unit":"g"},{"name":"grated low-moisture mozzarella","amount":"100","unit":"g"},{"name":"grated Parmesan","amount":"25","unit":"g"},{"name":"beaten egg for brushing","amount":"50","unit":"g"}],"steps":[{"title":"Prepare the pastry","content":"Heat the oven to 200 °C, conventional heat. Put one sheet of pastry, about 25 × 35 cm, on baking parchment on a tray.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Prepare the pastry"},{"title":"Spread the filling","content":"Spread over 80 g pesto, leaving a 1 cm border. Scatter over 100 g mozzarella and 25 g Parmesan.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Spread the filling"},{"title":"Cover and chill","content":"Lay the second sheet on top and press gently. Refrigerate for 15 minutes so the pastry is cold for cutting.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Cover and chill"},{"title":"Cut the tree","content":"Cut a tall triangle with a small trunk at the bottom. Keep all the offcuts to bake alongside, using another tray if needed.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Cut the tree"},{"title":"Cut the branches","content":"Make horizontal cuts every 2 cm on both sides, leaving an uncut centre spine about 3 cm wide. Do not cut the trunk.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Cut the branches"},{"title":"Twist and brush","content":"Twist each side strip once or twice without detaching it. Brush the tree and the offcuts with beaten egg.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Twist and brush"},{"title":"Bake until golden","content":"Bake for 20–25 minutes until risen, golden and cooked underneath. Smaller offcuts may be ready earlier; remove them when golden.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Bake until golden"},{"title":"Serve to share","content":"Rest for 5 minutes, then move the tree onto a board. Serve warm with all the baked offcuts, divided between eight people.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Pesto and cheese puff pastry Christmas tree: Serve to share"}],"category":"Starters & appetizers","course":"Starter","cuisine":"International","difficulty":"Easy","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Pesto and cheese puff pastry Christmas tree"}],"video_urls":[],"keywords":["Pesto and cheese puff pastry Christmas tree","chilled rectangular puff pastry, two sheets about 25 × 35 cm","thick basil pesto","grated low-moisture mozzarella"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 of the tree and baked offcuts","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g × each ingredient weight / 100, divided by the number of servings.","note":"Recipe-based estimate; brands, actual portions and cooking losses affect the values. Not a laboratory analysis."},"seo":{"title":"Pesto and cheese puff pastry Christmas tree | Manual de Cocina","description":"Two sheets of puff pastry enclose basil pesto, mozzarella and Parmesan. Twist the side strips into branches for a warm Christmas centrepiece to share.","image_alt":"Pesto and cheese puff pastry Christmas tree","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"Can I shape it ahead?","a":"Yes. Cover the unbaked tree and refrigerate for up to 12 hours. Brush with egg and bake before serving."},{"q":"Why chill before cutting?","a":"Cold pastry holds its layers and is easier to twist without distorting the branches."},{"q":"What happens to the offcuts?","a":"Bake them as snacks. The yield and nutrition count all the pastry and filling, with nothing discarded."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"sapin-feuillete-pesto-fromage","public_path":"/fr/sapin-feuillete-pesto-fromage","title":"Sapin feuilleté au pesto et au fromage","excerpt":"Deux pâtes feuilletées renferment du pesto de basilic, de la mozzarella et du parmesan. Les bandes latérales torsadées forment les branches d’un sapin de Noël à partager tiède.","summary":"Deux pâtes feuilletées renferment du pesto de basilic, de la mozzarella et du parmesan. Les bandes latérales torsadées forment les branches d’un sapin de Noël à partager tiède.","notes":"Gardez la pâte froide, utilisez un pesto épais et ne coupez pas la bande centrale. Faites cuire et servez toutes les chutes : elles sont comprises dans les portions et la nutrition. Le calcul inclut un œuf entier de dorure, même s’il en reste. Contient blé, lait, œuf et les fruits à coque du pesto. Réfrigérez les restes sous 2 heures, jusqu’à 2 jours, puis réchauffez au four.","content_html":"<p>Deux pâtes feuilletées renferment du pesto de basilic, de la mozzarella et du parmesan. Les bandes latérales torsadées forment les branches d’un sapin de Noël à partager tiède.</p><p>Gardez la pâte froide, utilisez un pesto épais et ne coupez pas la bande centrale. Faites cuire et servez toutes les chutes : elles sont comprises dans les portions et la nutrition. Le calcul inclut un œuf entier de dorure, même s’il en reste. Contient blé, lait, œuf et les fruits à coque du pesto. Réfrigérez les restes sous 2 heures, jusqu’à 2 jours, puis réchauffez au four.</p>","ingredients":[{"name":"pâte feuilletée rectangulaire réfrigérée, deux plaques d’environ 25 × 35 cm","amount":"500","unit":"g"},{"name":"pesto de basilic épais","amount":"80","unit":"g"},{"name":"mozzarella peu humide râpée","amount":"100","unit":"g"},{"name":"parmesan râpé","amount":"25","unit":"g"},{"name":"œuf battu pour dorer","amount":"50","unit":"g"}],"steps":[{"title":"Préparer la pâte","content":"Préchauffez le four à 200 °C en chaleur statique. Posez une plaque de pâte d’environ 25 × 35 cm sur du papier cuisson, sur une plaque de four.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Préparer la pâte"},{"title":"Étaler la garniture","content":"Étalez 80 g de pesto en laissant 1 cm de bord. Parsemez de 100 g de mozzarella et 25 g de parmesan.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Étaler la garniture"},{"title":"Recouvrir et refroidir","content":"Posez la deuxième pâte dessus et pressez doucement. Réfrigérez 15 minutes avant de découper.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Recouvrir et refroidir"},{"title":"Découper le sapin","content":"Découpez un grand triangle avec un petit tronc à la base. Conservez toutes les chutes pour les cuire à côté, sur une autre plaque si nécessaire.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Découper le sapin"},{"title":"Tracer les branches","content":"Faites des incisions horizontales tous les 2 cm de chaque côté, sans couper une bande centrale d’environ 3 cm ni le tronc.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Tracer les branches"},{"title":"Torsader et dorer","content":"Tournez chaque bande une ou deux fois sans la détacher. Badigeonnez d’œuf le sapin et les chutes.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Torsader et dorer"},{"title":"Cuire jusqu’à dorure","content":"Enfournez 20–25 minutes : la pâte doit être gonflée, dorée et cuite dessous. Retirez les petites chutes plus tôt si elles sont déjà dorées.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Cuire jusqu’à dorure"},{"title":"Servir à partager","content":"Laissez reposer 5 minutes puis transférez sur une planche. Servez tiède avec toutes les chutes cuites, pour huit personnes.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Sapin feuilleté au pesto et au fromage: Servir à partager"}],"category":"Entrées et apéritifs","course":"Entrée","cuisine":"Internationale","difficulty":"Facile","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Sapin feuilleté au pesto et au fromage"}],"video_urls":[],"keywords":["Sapin feuilleté au pesto et au fromage","pâte feuilletée rectangulaire réfrigérée, deux plaques d’environ 25 × 35 cm","pesto de basilic épais","mozzarella peu humide râpée"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 du sapin et des chutes cuites","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g × poids de chaque ingrédient / 100, divisée par le nombre de portions.","note":"Estimation selon la formulation ; les marques, les portions réelles et les pertes de cuisson modifient les valeurs. Pas une analyse de laboratoire."},"seo":{"title":"Sapin feuilleté au pesto et au fromage | Manual de Cocina","description":"Deux pâtes feuilletées renferment du pesto de basilic, de la mozzarella et du parmesan. Les bandes latérales torsadées forment les branches d’un sapin de Noël à partager tiède.","image_alt":"Sapin feuilleté au pesto et au fromage","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"Peut-on le façonner à l’avance ?","a":"Oui. Gardez le sapin cru couvert au réfrigérateur jusqu’à 12 heures. Dorez puis enfournez avant de servir."},{"q":"Pourquoi refroidir la pâte ?","a":"Froide, elle garde mieux ses couches et se torsade sans déformer les branches."},{"q":"Que faire des chutes ?","a":"Faites-les cuire en petits feuilletés. Les portions et la nutrition comptent toute la pâte et toute la garniture."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"albero-pasta-sfoglia-pesto-formaggio","public_path":"/it/albero-pasta-sfoglia-pesto-formaggio","title":"Albero di pasta sfoglia con pesto e formaggio","excerpt":"Due rettangoli di sfoglia racchiudono pesto di basilico, mozzarella e parmigiano. Le strisce laterali attorcigliate formano i rami di un albero natalizio da condividere tiepido.","summary":"Due rettangoli di sfoglia racchiudono pesto di basilico, mozzarella e parmigiano. Le strisce laterali attorcigliate formano i rami di un albero natalizio da condividere tiepido.","notes":"Mantieni la sfoglia fredda, usa pesto denso e lascia intatta la fascia centrale. Cuoci e servi anche tutti i ritagli: porzioni e nutrizione li comprendono. Il calcolo include l’uovo intero della spennellatura anche se avanza. Contiene frumento, latte, uovo e l’eventuale frutta a guscio del pesto. Refrigera gli avanzi entro 2 ore per massimo 2 giorni e riscalda in forno.","content_html":"<p>Due rettangoli di sfoglia racchiudono pesto di basilico, mozzarella e parmigiano. Le strisce laterali attorcigliate formano i rami di un albero natalizio da condividere tiepido.</p><p>Mantieni la sfoglia fredda, usa pesto denso e lascia intatta la fascia centrale. Cuoci e servi anche tutti i ritagli: porzioni e nutrizione li comprendono. Il calcolo include l’uovo intero della spennellatura anche se avanza. Contiene frumento, latte, uovo e l’eventuale frutta a guscio del pesto. Refrigera gli avanzi entro 2 ore per massimo 2 giorni e riscalda in forno.</p>","ingredients":[{"name":"pasta sfoglia rettangolare refrigerata, due fogli di circa 25 × 35 cm","amount":"500","unit":"g"},{"name":"pesto di basilico denso","amount":"80","unit":"g"},{"name":"mozzarella poco umida grattugiata","amount":"100","unit":"g"},{"name":"parmigiano grattugiato","amount":"25","unit":"g"},{"name":"uovo sbattuto per spennellare","amount":"50","unit":"g"}],"steps":[{"title":"Prepara la sfoglia","content":"Preriscalda il forno statico a 200 °C. Posa un foglio di sfoglia di circa 25 × 35 cm su carta da forno in una teglia.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Prepara la sfoglia"},{"title":"Distribuisci il ripieno","content":"Spalma 80 g di pesto lasciando 1 cm di bordo. Aggiungi 100 g di mozzarella e 25 g di parmigiano.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Distribuisci il ripieno"},{"title":"Copri e raffredda","content":"Appoggia il secondo foglio e premi delicatamente. Metti in frigorifero per 15 minuti prima di tagliare.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Copri e raffredda"},{"title":"Ritaglia l’albero","content":"Taglia un triangolo alto con un piccolo tronco alla base. Conserva tutti i ritagli da cuocere accanto, usando un’altra teglia se serve.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Ritaglia l’albero"},{"title":"Incidi i rami","content":"Pratica tagli orizzontali ogni 2 cm su entrambi i lati, lasciando una fascia centrale intatta larga circa 3 cm. Non tagliare il tronco.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Incidi i rami"},{"title":"Attorciglia e spennella","content":"Gira ogni striscia laterale una o due volte senza staccarla. Spennella albero e ritagli con uovo sbattuto.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Attorciglia e spennella"},{"title":"Cuoci fino a doratura","content":"Inforna per 20–25 minuti, finché la sfoglia è gonfia, dorata e cotta sul fondo. Togli prima i ritagli piccoli se sono già dorati.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Cuoci fino a doratura"},{"title":"Servi da condividere","content":"Lascia riposare 5 minuti e trasferisci su un tagliere. Servi tiepido con tutti i ritagli cotti, dividendoli tra otto persone.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Albero di pasta sfoglia con pesto e formaggio: Servi da condividere"}],"category":"Antipasti","course":"Antipasto","cuisine":"Internazionale","difficulty":"Facile","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Albero di pasta sfoglia con pesto e formaggio"}],"video_urls":[],"keywords":["Albero di pasta sfoglia con pesto e formaggio","pasta sfoglia rettangolare refrigerata, due fogli di circa 25 × 35 cm","pesto di basilico denso","mozzarella poco umida grattugiata"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 dell’albero e dei ritagli cotti","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g × peso di ogni ingrediente / 100, divisa per il numero di porzioni.","note":"Stima della formulazione: marche, porzioni reali e perdite di cottura cambiano i valori. Non è un’analisi di laboratorio."},"seo":{"title":"Albero di pasta sfoglia con pesto e formaggio | Manual de Cocina","description":"Due rettangoli di sfoglia racchiudono pesto di basilico, mozzarella e parmigiano. Le strisce laterali attorcigliate formano i rami di un albero natalizio da condividere tiepido.","image_alt":"Albero di pasta sfoglia con pesto e formaggio","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"Posso formarlo in anticipo?","a":"Sì. Conserva l’albero crudo coperto in frigo fino a 12 ore. Spennella con uovo e cuoci prima di servire."},{"q":"Perché raffreddare la sfoglia?","a":"Da fredda mantiene gli strati e permette di attorcigliare i rami senza deformarli."},{"q":"Che cosa faccio con i ritagli?","a":"Cuocili come piccoli salatini. Le porzioni e la nutrizione includono tutta la sfoglia e tutto il ripieno."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"pesto-cheese-puff-pastry-tree","public_path":"/ja/pesto-cheese-puff-pastry-tree","title":"ペストとチーズのクリスマスツリーパイ","excerpt":"2枚のパイシートにバジルペスト、モッツァレラ、パルメザンをはさみます。左右の切り込みをねじって枝にした、温かいまま分け合うクリスマス向けの前菜です。","summary":"2枚のパイシートにバジルペスト、モッツァレラ、パルメザンをはさみます。左右の切り込みをねじって枝にした、温かいまま分け合うクリスマス向けの前菜です。","notes":"パイ生地は冷たいまま扱い、水分の少ないペストを使います。中心の帯は切り離しません。切れ端もすべて焼いて出し、分量と栄養価に含めます。塗り卵は余っても全量を計算しています。小麦、乳、卵と、ペストに使われるナッツ類を含みます。残りは2時間以内に冷蔵し、2日以内にオーブンで温め直して食べます。","content_html":"<p>2枚のパイシートにバジルペスト、モッツァレラ、パルメザンをはさみます。左右の切り込みをねじって枝にした、温かいまま分け合うクリスマス向けの前菜です。</p><p>パイ生地は冷たいまま扱い、水分の少ないペストを使います。中心の帯は切り離しません。切れ端もすべて焼いて出し、分量と栄養価に含めます。塗り卵は余っても全量を計算しています。小麦、乳、卵と、ペストに使われるナッツ類を含みます。残りは2時間以内に冷蔵し、2日以内にオーブンで温め直して食べます。</p>","ingredients":[{"name":"冷蔵の長方形パイシート（約25 × 35 cmを2枚）","amount":"500","unit":"g"},{"name":"濃いバジルペスト","amount":"80","unit":"g"},{"name":"水分の少ないモッツァレラチーズ（すりおろす）","amount":"100","unit":"g"},{"name":"パルメザンチーズ（すりおろす）","amount":"25","unit":"g"},{"name":"表面用の溶き卵","amount":"50","unit":"g"}],"steps":[{"title":"パイシートを用意する","content":"上下加熱のオーブンを200 ℃に予熱します。約25 × 35 cmのシート1枚を、オーブン用シートを敷いた天板に置きます。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: パイシートを用意する"},{"title":"具を広げる","content":"縁を1 cm残してペスト80 gを薄く広げ、モッツァレラ100 gとパルメザン25 gを散らします。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: 具を広げる"},{"title":"重ねて冷やす","content":"もう1枚を重ねて軽く押さえます。切る前に冷蔵庫で15分冷やします。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: 重ねて冷やす"},{"title":"ツリーを切り抜く","content":"下に小さな幹を残した縦長の三角形に切ります。切れ端はすべて取っておき、必要なら別の天板で一緒に焼きます。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: ツリーを切り抜く"},{"title":"枝に切り込みを入れる","content":"両側から2 cm間隔で水平に切り込みを入れ、中心約3 cmの帯と幹は切らずに残します。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: 枝に切り込みを入れる"},{"title":"ねじって卵を塗る","content":"左右の帯をそれぞれ1〜2回ねじります。中心から外さないようにし、ツリーと切れ端に溶き卵を塗ります。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: ねじって卵を塗る"},{"title":"きつね色に焼く","content":"20〜25分、膨らんできつね色になり底まで焼けるまで加熱します。小さい切れ端は早く焼けるので、色づいたら先に取り出します。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: きつね色に焼く"},{"title":"分け合って食べる","content":"取り出して5分置き、木のボードに移します。焼いた切れ端もすべて添え、温かいうちに8人で分けます。","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"ペストとチーズのクリスマスツリーパイ: 分け合って食べる"}],"category":"前菜・おつまみ","course":"前菜","cuisine":"各国料理","difficulty":"簡単","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"ペストとチーズのクリスマスツリーパイ"}],"video_urls":[],"keywords":["ペストとチーズのクリスマスツリーパイ","冷蔵の長方形パイシート（約25 × 35 cmを2枚）","濃いバジルペスト","水分の少ないモッツァレラチーズ（すりおろす）"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"ツリーと焼いた切れ端の8分の1","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"材料100 gあたりの栄養価×各使用重量÷100を合計し、人数で割って算出。","note":"配合からの推定値です。製品、実際の盛り付け量、加熱による損失で変わります。検査機関での分析値ではありません。"},"seo":{"title":"ペストとチーズのクリスマスツリーパイ | Manual de Cocina","description":"2枚のパイシートにバジルペスト、モッツァレラ、パルメザンをはさみます。左右の切り込みをねじって枝にした、温かいまま分け合うクリスマス向けの前菜です。","image_alt":"ペストとチーズのクリスマスツリーパイ","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"先に成形しておけますか？","a":"はい。焼く前の状態で覆い、冷蔵庫で12時間まで保存できます。卵を塗って食べる前に焼きます。"},{"q":"切る前に冷やす理由は？","a":"冷たい生地の方が層を保ちやすく、枝をねじっても形が崩れにくいためです。"},{"q":"切れ端はどうしますか？","a":"小さなパイとして焼きます。分量と栄養価には生地と具の全量を含めています。"}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"arvore-massa-folhada-pesto-queijo","public_path":"/pt/arvore-massa-folhada-pesto-queijo","title":"Árvore de massa folhada com pesto e queijo para o Natal","excerpt":"Duas folhas de massa folhada envolvem pesto de manjericão, muçarela e parmesão. As tiras laterais torcidas formam os galhos de uma árvore natalina para compartilhar morna.","summary":"Duas folhas de massa folhada envolvem pesto de manjericão, muçarela e parmesão. As tiras laterais torcidas formam os galhos de uma árvore natalina para compartilhar morna.","notes":"Mantenha a massa fria, use pesto espesso e deixe a faixa central intacta. Asse e sirva todas as aparas: elas entram no rendimento e na nutrição. O cálculo inclui o ovo inteiro usado para pincelar, mesmo que sobre. Contém trigo, leite, ovo e as oleaginosas presentes no pesto. Refrigere as sobras em até 2 horas, guarde por até 2 dias e reaqueça no forno.","content_html":"<p>Duas folhas de massa folhada envolvem pesto de manjericão, muçarela e parmesão. As tiras laterais torcidas formam os galhos de uma árvore natalina para compartilhar morna.</p><p>Mantenha a massa fria, use pesto espesso e deixe a faixa central intacta. Asse e sirva todas as aparas: elas entram no rendimento e na nutrição. O cálculo inclui o ovo inteiro usado para pincelar, mesmo que sobre. Contém trigo, leite, ovo e as oleaginosas presentes no pesto. Refrigere as sobras em até 2 horas, guarde por até 2 dias e reaqueça no forno.</p>","ingredients":[{"name":"massa folhada retangular refrigerada, duas folhas de cerca de 25 × 35 cm","amount":"500","unit":"g"},{"name":"pesto de manjericão espesso","amount":"80","unit":"g"},{"name":"muçarela de baixa umidade ralada","amount":"100","unit":"g"},{"name":"parmesão ralado","amount":"25","unit":"g"},{"name":"ovo batido para pincelar","amount":"50","unit":"g"}],"steps":[{"title":"Prepare a massa","content":"Preaqueça o forno a 200 °C, com calor superior e inferior. Coloque uma folha de massa de cerca de 25 × 35 cm sobre papel-manteiga em uma assadeira.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-01.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Prepare a massa"},{"title":"Espalhe o recheio","content":"Passe 80 g de pesto, deixando 1 cm de borda. Distribua 100 g de muçarela e 25 g de parmesão.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-02.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Espalhe o recheio"},{"title":"Cubra e esfrie","content":"Coloque a segunda folha por cima e pressione suavemente. Leve à geladeira por 15 minutos antes de cortar.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-03.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Cubra e esfrie"},{"title":"Recorte a árvore","content":"Corte um triângulo alto com um pequeno tronco na base. Reserve todas as aparas para assar junto, em outra assadeira se necessário.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-04.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Recorte a árvore"},{"title":"Corte os galhos","content":"Faça cortes horizontais a cada 2 cm dos dois lados, deixando uma faixa central de cerca de 3 cm intacta. Não corte o tronco.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-05.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Corte os galhos"},{"title":"Torça e pincele","content":"Gire cada tira lateral uma ou duas vezes, sem soltá-la do centro. Pincele a árvore e as aparas com ovo batido.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-06.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Torça e pincele"},{"title":"Asse até dourar","content":"Asse por 20–25 minutos, até crescer, dourar e cozinhar por baixo. As aparas pequenas podem ficar prontas antes: retire quando dourarem.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-07.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Asse até dourar"},{"title":"Sirva para compartilhar","content":"Deixe descansar por 5 minutos e transfira para uma tábua. Sirva morna com todas as aparas assadas, dividindo entre oito pessoas.","image_url":"/recetas/arbol-hojaldre-pesto-queso/paso-08.webp","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal: Sirva para compartilhar"}],"category":"Entradas e aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":25,"cook_time_minutes":25,"total_time_minutes":70,"servings":8,"image_url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","gallery":[{"url":"/recetas/arbol-hojaldre-pesto-queso/portada.webp","alt":"Árvore de massa folhada com pesto e queijo para o Natal"}],"video_urls":[],"keywords":["Árvore de massa folhada com pesto e queijo para o Natal","massa folhada retangular refrigerada, duas folhas de cerca de 25 × 35 cm","pesto de manjericão espesso","muçarela de baixa umidade ralada"],"nutrition":{"calories":334,"protein_g":8.7,"carbs_g":24.3,"fat_g":21.1,"saturated_fat_g":8.8,"fiber_g":1.5,"sugar_g":1,"sodium_mg":452,"estimated":true,"serving_size":"1/8 da árvore e das aparas assadas","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g × peso de cada ingrediente / 100, dividida pelo número de porções.","note":"Estimativa pela formulação; marcas, porções reais e perdas no cozimento alteram os valores. Não é análise laboratorial."},"seo":{"title":"Árvore de massa folhada com pesto e queijo para o Natal | Manual de Cocina","description":"Duas folhas de massa folhada envolvem pesto de manjericão, muçarela e parmesão. As tiras laterais torcidas formam os galhos de uma árvore natalina para compartilhar morna.","image_alt":"Árvore de massa folhada com pesto e queijo para o Natal","image_variants":["/recetas/arbol-hojaldre-pesto-queso/portada-1x1.webp","/recetas/arbol-hojaldre-pesto-queso/portada-4x3.webp","/recetas/arbol-hojaldre-pesto-queso/portada-16x9.webp"],"faq":[{"q":"Posso montar antes da ceia?","a":"Sim. Guarde a árvore crua coberta na geladeira por até 12 horas. Pincele e asse na hora de servir."},{"q":"Por que gelar antes de cortar?","a":"A massa fria preserva as camadas e facilita torcer os galhos sem deformá-los."},{"q":"O que faço com as aparas?","a":"Asse como pequenos salgados. O rendimento e a nutrição consideram toda a massa e todo o recheio."}],"rest_time_minutes":20},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"es","slug":"bocaditos-hojaldre-brie-arandanos","public_path":"/bocaditos-hojaldre-brie-arandanos","title":"Bocaditos de hojaldre con brie y arándanos rojos","excerpt":"Doce canastitas de hojaldre con brie fundido, salsa de arándanos rojos y nuez. Un aperitivo de contraste dulce y salado que se hornea en molde de muffins.","summary":"Doce canastitas de hojaldre con brie fundido, salsa de arándanos rojos y nuez. Un aperitivo de contraste dulce y salado que se hornea en molde de muffins.","notes":"Utiliza salsa o mermelada espesa de arándanos rojos (cranberry), no arándanos azules frescos. Una lámina de unos 24 × 32 cm permite cortar 12 cuadrados de 8 cm sin desperdicio. Usa un molde metálico de 12 muffins estándar y no lo llenes hasta el borde. Contiene trigo, leche y nueces. Refrigera las sobras dentro de 2 horas, hasta 2 días; recalienta en horno hasta que estén calientes. Los tiempos son orientativos y dependen de la masa y el molde.","content_html":"<p>Doce canastitas de hojaldre con brie fundido, salsa de arándanos rojos y nuez. Un aperitivo de contraste dulce y salado que se hornea en molde de muffins.</p><p>Utiliza salsa o mermelada espesa de arándanos rojos (cranberry), no arándanos azules frescos. Una lámina de unos 24 × 32 cm permite cortar 12 cuadrados de 8 cm sin desperdicio. Usa un molde metálico de 12 muffins estándar y no lo llenes hasta el borde. Contiene trigo, leche y nueces. Refrigera las sobras dentro de 2 horas, hasta 2 días; recalienta en horno hasta que estén calientes. Los tiempos son orientativos y dependen de la masa y el molde.</p>","ingredients":[{"name":"hojaldre refrigerado rectangular, unos 24 × 32 cm","amount":"250","unit":"g"},{"name":"queso brie con corteza comestible","amount":"180","unit":"g"},{"name":"salsa espesa de arándanos rojos","amount":"120","unit":"g"},{"name":"nueces peladas picadas","amount":"30","unit":"g"},{"name":"aceite para engrasar el molde","amount":"5","unit":"g"},{"name":"romero fresco, solo las hojas picadas","amount":"2","unit":"g"}],"steps":[{"title":"Prepara el molde","content":"Precalienta el horno a 200 °C, calor arriba y abajo. Engrasa ligeramente con 5 g de aceite un molde metálico de 12 muffins estándar.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Prepara el molde"},{"title":"Corta los cuadrados","content":"Desenrolla 250 g de hojaldre frío en un rectángulo de unos 24 × 32 cm. Corta una cuadrícula de 3 × 4 para obtener 12 cuadrados de 8 cm.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Corta los cuadrados"},{"title":"Forma las canastitas","content":"Acomoda un cuadrado en cada cavidad del molde y presiona suavemente el fondo, dejando las puntas hacia arriba.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Forma las canastitas"},{"title":"Reparte el brie","content":"Corta 180 g de brie en 12 porciones iguales de unos 15 g y coloca una en cada base. La corteza comestible puede quedarse.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Reparte el brie"},{"title":"Añade los arándanos","content":"Pon 10 g de salsa espesa de arándanos rojos sobre cada trozo de brie, sin llenar la cavidad hasta arriba.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Añade los arándanos"},{"title":"Termina con nuez","content":"Reparte 30 g de nueces picadas y 2 g de hojas de romero sobre las 12 canastitas.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Termina con nuez"},{"title":"Hornea las canastitas","content":"Hornea 18–20 minutos, hasta que los bordes estén bien dorados y la base cocida. Si la parte superior se dora demasiado, cubre flojamente con aluminio al final.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Hornea las canastitas"},{"title":"Desmolda y sirve","content":"Espera 5 minutos antes de sacar las canastitas con una cuchara pequeña. Sirve 2 bocaditos tibios por persona; el queso caliente puede quemar.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos: Desmolda y sirve"}],"category":"Entrantes y aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Bocaditos de hojaldre con brie y arándanos rojos"}],"video_urls":[],"keywords":["Bocaditos de hojaldre con brie y arándanos rojos","hojaldre refrigerado rectangular, unos 24 × 32 cm","queso brie con corteza comestible","salsa espesa de arándanos rojos"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 de los 12 bocaditos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g × peso de cada ingrediente / 100, dividida por las porciones.","note":"Estimación de la formulación; cambia según marcas, porción real y pérdidas de cocción. No es un análisis de laboratorio."},"seo":{"title":"Bocaditos de hojaldre con brie y arándanos rojos | Manual de Cocina","description":"Doce canastitas de hojaldre con brie fundido, salsa de arándanos rojos y nuez. Un aperitivo de contraste dulce y salado que se hornea en molde de muffins.","image_alt":"Bocaditos de hojaldre con brie y arándanos rojos","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"¿Son arándanos azules o rojos?","a":"Rojos, también llamados cranberry, en salsa espesa o mermelada. El arándano azul produce otro sabor."},{"q":"¿Se quita la corteza del brie?","a":"No hace falta: es comestible y ayuda a contener el queso. Retírala solo si lo prefieres."},{"q":"¿Puedo omitir las nueces?","a":"Sí. Omítelas si hay alergia y revisa el resto de las etiquetas; la nutrición publicada corresponde a la versión con nueces."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"blaetterteig-haeppchen-brie-cranberry","public_path":"/de/blaetterteig-haeppchen-brie-cranberry","title":"Blätterteig-Häppchen mit Brie und Cranberrys","excerpt":"Zwölf kleine Blätterteigkörbchen mit geschmolzenem Brie, dickem Cranberrykompott und Walnüssen. Sie werden in einer normalen Muffinform gebacken und warm serviert.","summary":"Zwölf kleine Blätterteigkörbchen mit geschmolzenem Brie, dickem Cranberrykompott und Walnüssen. Sie werden in einer normalen Muffinform gebacken und warm serviert.","notes":"Dickes Kompott aus roten Cranberrys verwenden, keine frischen Heidelbeeren. Eine 24 × 32 cm große Platte ergibt zwölf Quadrate ohne Verschnitt. Eine Metallform für zwölf normale Muffins verwenden und nicht überfüllen. Enthält Weizen, Milch und Walnüsse. Reste innerhalb von 2 Stunden kühlen, bis zu 2 Tage lagern und im Ofen erwärmen. Die Backzeit hängt von Teig und Form ab.","content_html":"<p>Zwölf kleine Blätterteigkörbchen mit geschmolzenem Brie, dickem Cranberrykompott und Walnüssen. Sie werden in einer normalen Muffinform gebacken und warm serviert.</p><p>Dickes Kompott aus roten Cranberrys verwenden, keine frischen Heidelbeeren. Eine 24 × 32 cm große Platte ergibt zwölf Quadrate ohne Verschnitt. Eine Metallform für zwölf normale Muffins verwenden und nicht überfüllen. Enthält Weizen, Milch und Walnüsse. Reste innerhalb von 2 Stunden kühlen, bis zu 2 Tage lagern und im Ofen erwärmen. Die Backzeit hängt von Teig und Form ab.</p>","ingredients":[{"name":"gekühlter rechteckiger Blätterteig, etwa 24 × 32 cm","amount":"250","unit":"g"},{"name":"Brie mit essbarer Rinde","amount":"180","unit":"g"},{"name":"dickes Cranberrykompott","amount":"120","unit":"g"},{"name":"gehackte Walnusskerne","amount":"30","unit":"g"},{"name":"Öl für die Form","amount":"5","unit":"g"},{"name":"fein gehackte frische Rosmarinnadeln","amount":"2","unit":"g"}],"steps":[{"title":"Form vorbereiten","content":"Ofen auf 200 °C Ober-/Unterhitze vorheizen. Eine Metallform für zwölf normale Muffins mit 5 g Öl dünn einfetten.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Form vorbereiten"},{"title":"Quadrate schneiden","content":"250 g kalten Blätterteig auf etwa 24 × 32 cm ausrollen. In einem Raster von 3 × 4 zwölf Quadrate von 8 cm schneiden.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Quadrate schneiden"},{"title":"Körbchen formen","content":"Je ein Quadrat vorsichtig in jede Vertiefung drücken. Die Ecken zeigen nach oben.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Körbchen formen"},{"title":"Brie verteilen","content":"180 g Brie in zwölf gleich große Stücke von etwa 15 g schneiden und je eines hineinlegen. Die essbare Rinde darf bleiben.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Brie verteilen"},{"title":"Cranberrys zugeben","content":"Je 10 g dickes Cranberrykompott auf den Brie geben. Die Vertiefungen nicht randvoll füllen.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Cranberrys zugeben"},{"title":"Mit Nüssen ergänzen","content":"30 g gehackte Walnüsse und 2 g gehackten Rosmarin auf die Körbchen verteilen.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Mit Nüssen ergänzen"},{"title":"Körbchen backen","content":"18–20 Minuten backen, bis die Ränder goldbraun und die Böden durchgebacken sind. Bei zu starker Bräunung zum Schluss locker mit Alufolie abdecken.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Körbchen backen"},{"title":"Herausnehmen und servieren","content":"5 Minuten warten, dann mit einem kleinen Löffel aus der Form heben. Je zwei lauwarme Häppchen servieren; der Käse kann sehr heiß sein.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys: Herausnehmen und servieren"}],"category":"Vorspeisen","course":"Vorspeise","cuisine":"International","difficulty":"Einfach","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Blätterteig-Häppchen mit Brie und Cranberrys"}],"video_urls":[],"keywords":["Blätterteig-Häppchen mit Brie und Cranberrys","gekühlter rechteckiger Blätterteig, etwa 24 × 32 cm","Brie mit essbarer Rinde","dickes Cranberrykompott"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 von 12 Blätterteig-Häppchen","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Summe der Nährwerte je 100 g × Zutatengewicht / 100, geteilt durch die Portionenzahl.","note":"Schätzung aus der Rezeptur; Marke, tatsächliche Portion und Garverluste verändern die Werte. Keine Laboranalyse."},"seo":{"title":"Blätterteig-Häppchen mit Brie und Cranberrys | Manual de Cocina","description":"Zwölf kleine Blätterteigkörbchen mit geschmolzenem Brie, dickem Cranberrykompott und Walnüssen. Sie werden in einer normalen Muffinform gebacken und warm serviert.","image_alt":"Blätterteig-Häppchen mit Brie und Cranberrys","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"Sind Heidelbeeren gemeint?","a":"Nein. Benötigt werden rote Cranberrys als dickes Kompott oder Konfitüre."},{"q":"Muss die Brie-Rinde weg?","a":"Nein. Sie ist essbar und hilft, den Käse zusammenzuhalten. Nur nach Geschmack entfernen."},{"q":"Kann ich die Walnüsse weglassen?","a":"Ja. Bei Allergien weglassen und alle Etiketten prüfen. Die angegebenen Nährwerte enthalten Walnüsse."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"cranberry-brie-puff-pastry-bites","public_path":"/en/cranberry-brie-puff-pastry-bites","title":"Cranberry and brie puff pastry bites","excerpt":"Twelve little pastry cups hold melted brie, thick cranberry sauce and walnuts. Bake them in a standard muffin tin for an easy sweet and savoury party appetiser.","summary":"Twelve little pastry cups hold melted brie, thick cranberry sauce and walnuts. Bake them in a standard muffin tin for an easy sweet and savoury party appetiser.","notes":"Use thick red cranberry sauce, not fresh blueberries. A 24 × 32 cm sheet makes twelve 8 cm squares without waste. Use a metal tin for 12 standard muffins and avoid overfilling. Contains wheat, milk and walnuts. Refrigerate leftovers within 2 hours for up to 2 days, then reheat in the oven. Baking time depends on the pastry and tin.","content_html":"<p>Twelve little pastry cups hold melted brie, thick cranberry sauce and walnuts. Bake them in a standard muffin tin for an easy sweet and savoury party appetiser.</p><p>Use thick red cranberry sauce, not fresh blueberries. A 24 × 32 cm sheet makes twelve 8 cm squares without waste. Use a metal tin for 12 standard muffins and avoid overfilling. Contains wheat, milk and walnuts. Refrigerate leftovers within 2 hours for up to 2 days, then reheat in the oven. Baking time depends on the pastry and tin.</p>","ingredients":[{"name":"chilled rectangular puff pastry, about 24 × 32 cm","amount":"250","unit":"g"},{"name":"brie with edible rind","amount":"180","unit":"g"},{"name":"thick cranberry sauce","amount":"120","unit":"g"},{"name":"chopped shelled walnuts","amount":"30","unit":"g"},{"name":"oil for greasing","amount":"5","unit":"g"},{"name":"finely chopped fresh rosemary leaves","amount":"2","unit":"g"}],"steps":[{"title":"Prepare the tin","content":"Heat the conventional oven to 200 °C. Lightly grease a metal 12-hole standard muffin tin with 5 g oil.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Cranberry and brie puff pastry bites: Prepare the tin"},{"title":"Cut the squares","content":"Unroll 250 g cold pastry into a rectangle about 24 × 32 cm. Cut a 3 × 4 grid to make twelve 8 cm squares.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Cranberry and brie puff pastry bites: Cut the squares"},{"title":"Line the holes","content":"Press one square gently into each hole, leaving the corners pointing upwards.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Cranberry and brie puff pastry bites: Line the holes"},{"title":"Add the brie","content":"Cut 180 g brie into twelve equal pieces of about 15 g. Put one in each pastry cup; the edible rind can stay.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Cranberry and brie puff pastry bites: Add the brie"},{"title":"Add cranberry sauce","content":"Spoon 10 g thick cranberry sauce over the brie in each cup. Do not fill the holes to the brim.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Cranberry and brie puff pastry bites: Add cranberry sauce"},{"title":"Add walnuts","content":"Divide 30 g chopped walnuts and 2 g chopped rosemary leaves between the cups.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Cranberry and brie puff pastry bites: Add walnuts"},{"title":"Bake the cups","content":"Bake for 18–20 minutes until the edges are golden and the bases cooked. Cover loosely with foil near the end if the tops brown too quickly.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Cranberry and brie puff pastry bites: Bake the cups"},{"title":"Unmould and serve","content":"Wait 5 minutes before lifting the bites out with a small spoon. Serve two warm bites per person; the melted cheese will be hot.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Cranberry and brie puff pastry bites: Unmould and serve"}],"category":"Starters & appetizers","course":"Starter","cuisine":"International","difficulty":"Easy","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Cranberry and brie puff pastry bites"}],"video_urls":[],"keywords":["Cranberry and brie puff pastry bites","chilled rectangular puff pastry, about 24 × 32 cm","brie with edible rind","thick cranberry sauce"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 of 12 pastry bites","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g × each ingredient weight / 100, divided by the number of servings.","note":"Recipe-based estimate; brands, actual portions and cooking losses affect the values. Not a laboratory analysis."},"seo":{"title":"Cranberry and brie puff pastry bites | Manual de Cocina","description":"Twelve little pastry cups hold melted brie, thick cranberry sauce and walnuts. Bake them in a standard muffin tin for an easy sweet and savoury party appetiser.","image_alt":"Cranberry and brie puff pastry bites","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"Are these made with blueberries?","a":"No. Use red cranberries in a thick sauce or preserve; blueberries make a different recipe."},{"q":"Must I remove the brie rind?","a":"No. The rind is edible and helps contain the cheese. Remove it only if you prefer."},{"q":"Can I leave out the walnuts?","a":"Yes. Omit them for a nut-free adaptation and check every label. The published nutrition includes the walnuts."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"bouchees-feuilletees-brie-cranberries","public_path":"/fr/bouchees-feuilletees-brie-cranberries","title":"Bouchées feuilletées au brie et aux cranberries","excerpt":"Douze petits paniers feuilletés garnis de brie fondant, de sauce épaisse aux cranberries et de noix. Ils cuisent dans un moule à muffins standard pour un apéritif sucré-salé.","summary":"Douze petits paniers feuilletés garnis de brie fondant, de sauce épaisse aux cranberries et de noix. Ils cuisent dans un moule à muffins standard pour un apéritif sucré-salé.","notes":"Utilisez des cranberries rouges en sauce épaisse, pas des myrtilles fraîches. Une pâte de 24 × 32 cm donne douze carrés de 8 cm sans chute. Choisissez un moule métallique pour douze muffins standards et ne remplissez pas à ras bord. Contient blé, lait et noix. Réfrigérez les restes sous 2 heures jusqu’à 2 jours, puis réchauffez au four. Adaptez la cuisson à la pâte et au moule.","content_html":"<p>Douze petits paniers feuilletés garnis de brie fondant, de sauce épaisse aux cranberries et de noix. Ils cuisent dans un moule à muffins standard pour un apéritif sucré-salé.</p><p>Utilisez des cranberries rouges en sauce épaisse, pas des myrtilles fraîches. Une pâte de 24 × 32 cm donne douze carrés de 8 cm sans chute. Choisissez un moule métallique pour douze muffins standards et ne remplissez pas à ras bord. Contient blé, lait et noix. Réfrigérez les restes sous 2 heures jusqu’à 2 jours, puis réchauffez au four. Adaptez la cuisson à la pâte et au moule.</p>","ingredients":[{"name":"pâte feuilletée rectangulaire réfrigérée, environ 24 × 32 cm","amount":"250","unit":"g"},{"name":"brie avec croûte comestible","amount":"180","unit":"g"},{"name":"sauce épaisse aux cranberries rouges","amount":"120","unit":"g"},{"name":"cerneaux de noix hachés","amount":"30","unit":"g"},{"name":"huile pour le moule","amount":"5","unit":"g"},{"name":"feuilles de romarin frais finement hachées","amount":"2","unit":"g"}],"steps":[{"title":"Préparer le moule","content":"Préchauffez le four à 200 °C en chaleur statique. Huilez légèrement avec 5 g d’huile un moule métallique à douze muffins standards.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Préparer le moule"},{"title":"Découper les carrés","content":"Déroulez 250 g de pâte froide en rectangle d’environ 24 × 32 cm. Découpez une grille de 3 × 4 pour obtenir douze carrés de 8 cm.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Découper les carrés"},{"title":"Former les paniers","content":"Placez un carré dans chaque empreinte et pressez doucement le fond, pointes relevées.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Former les paniers"},{"title":"Répartir le brie","content":"Coupez 180 g de brie en douze morceaux d’environ 15 g. Déposez-en un par panier, avec sa croûte comestible.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Répartir le brie"},{"title":"Ajouter les cranberries","content":"Déposez 10 g de sauce épaisse aux cranberries sur chaque morceau de brie, sans remplir jusqu’en haut.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Ajouter les cranberries"},{"title":"Ajouter noix et romarin","content":"Répartissez 30 g de noix hachées et 2 g de feuilles de romarin sur les douze paniers.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Ajouter noix et romarin"},{"title":"Cuire les bouchées","content":"Enfournez 18–20 minutes, jusqu’à ce que les bords soient dorés et les fonds cuits. Couvrez lâchement d’aluminium en fin de cuisson si le dessus colore trop.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Cuire les bouchées"},{"title":"Démouler et servir","content":"Attendez 5 minutes puis soulevez les bouchées avec une petite cuillère. Servez deux bouchées tièdes par personne ; le fromage peut être brûlant.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Bouchées feuilletées au brie et aux cranberries: Démouler et servir"}],"category":"Entrées et apéritifs","course":"Entrée","cuisine":"Internationale","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Bouchées feuilletées au brie et aux cranberries"}],"video_urls":[],"keywords":["Bouchées feuilletées au brie et aux cranberries","pâte feuilletée rectangulaire réfrigérée, environ 24 × 32 cm","brie avec croûte comestible","sauce épaisse aux cranberries rouges"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 bouchées sur 12","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g × poids de chaque ingrédient / 100, divisée par le nombre de portions.","note":"Estimation selon la formulation ; les marques, les portions réelles et les pertes de cuisson modifient les valeurs. Pas une analyse de laboratoire."},"seo":{"title":"Bouchées feuilletées au brie et aux cranberries | Manual de Cocina","description":"Douze petits paniers feuilletés garnis de brie fondant, de sauce épaisse aux cranberries et de noix. Ils cuisent dans un moule à muffins standard pour un apéritif sucré-salé.","image_alt":"Bouchées feuilletées au brie et aux cranberries","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"S’agit-il de myrtilles ?","a":"Non. Il faut des cranberries rouges en sauce épaisse ou confiture. Les myrtilles donnent une autre saveur."},{"q":"Faut-il retirer la croûte du brie ?","a":"Non. Elle est comestible et aide à contenir le fromage. Retirez-la seulement selon votre goût."},{"q":"Peut-on omettre les noix ?","a":"Oui. En cas d’allergie, supprimez-les et vérifiez tous les emballages. Les valeurs publiées comprennent les noix."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"bocconcini-sfoglia-brie-mirtilli-rossi","public_path":"/it/bocconcini-sfoglia-brie-mirtilli-rossi","title":"Bocconcini di sfoglia con brie e mirtilli rossi","excerpt":"Dodici cestini di sfoglia con brie fuso, salsa densa di cranberry e noci. Si cuociono in uno stampo da muffin standard per un antipasto dolce e salato.","summary":"Dodici cestini di sfoglia con brie fuso, salsa densa di cranberry e noci. Si cuociono in uno stampo da muffin standard per un antipasto dolce e salato.","notes":"Usa salsa densa di cranberry rossi, non mirtilli blu freschi. Una sfoglia di 24 × 32 cm dà dodici quadrati da 8 cm senza scarti. Scegli uno stampo metallico da dodici muffin standard e non riempire fino al bordo. Contiene frumento, latte e noci. Refrigera gli avanzi entro 2 ore per massimo 2 giorni e riscalda in forno. La cottura dipende da sfoglia e stampo.","content_html":"<p>Dodici cestini di sfoglia con brie fuso, salsa densa di cranberry e noci. Si cuociono in uno stampo da muffin standard per un antipasto dolce e salato.</p><p>Usa salsa densa di cranberry rossi, non mirtilli blu freschi. Una sfoglia di 24 × 32 cm dà dodici quadrati da 8 cm senza scarti. Scegli uno stampo metallico da dodici muffin standard e non riempire fino al bordo. Contiene frumento, latte e noci. Refrigera gli avanzi entro 2 ore per massimo 2 giorni e riscalda in forno. La cottura dipende da sfoglia e stampo.</p>","ingredients":[{"name":"pasta sfoglia rettangolare refrigerata, circa 24 × 32 cm","amount":"250","unit":"g"},{"name":"brie con crosta edibile","amount":"180","unit":"g"},{"name":"salsa densa di cranberry o mirtilli rossi americani","amount":"120","unit":"g"},{"name":"gherigli di noce tritati","amount":"30","unit":"g"},{"name":"olio per lo stampo","amount":"5","unit":"g"},{"name":"foglioline di rosmarino fresco tritate","amount":"2","unit":"g"}],"steps":[{"title":"Prepara lo stampo","content":"Preriscalda il forno statico a 200 °C. Ungi leggermente con 5 g di olio uno stampo metallico per dodici muffin standard.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Prepara lo stampo"},{"title":"Taglia i quadrati","content":"Srotola 250 g di sfoglia fredda in un rettangolo di circa 24 × 32 cm. Taglia una griglia di 3 × 4 ottenendo dodici quadrati da 8 cm.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Taglia i quadrati"},{"title":"Forma i cestini","content":"Sistema un quadrato in ogni cavità, premendo piano sul fondo e lasciando le punte verso l’alto.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Forma i cestini"},{"title":"Aggiungi il brie","content":"Taglia 180 g di brie in dodici pezzi da circa 15 g e mettine uno in ogni cestino. Puoi lasciare la crosta edibile.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Aggiungi il brie"},{"title":"Unisci i cranberry","content":"Metti 10 g di salsa densa di cranberry su ogni pezzo di brie, senza riempire la cavità fino al bordo.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Unisci i cranberry"},{"title":"Completa con le noci","content":"Distribuisci 30 g di noci tritate e 2 g di foglioline di rosmarino sui dodici cestini.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Completa con le noci"},{"title":"Cuoci i cestini","content":"Inforna 18–20 minuti, finché i bordi sono dorati e il fondo cotto. Se la superficie scurisce troppo, copri morbidamente con alluminio alla fine.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Cuoci i cestini"},{"title":"Sforma e servi","content":"Attendi 5 minuti, poi solleva con un cucchiaino. Servi due bocconcini tiepidi a persona; il formaggio può scottare.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi: Sforma e servi"}],"category":"Antipasti","course":"Antipasto","cuisine":"Internazionale","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Bocconcini di sfoglia con brie e mirtilli rossi"}],"video_urls":[],"keywords":["Bocconcini di sfoglia con brie e mirtilli rossi","pasta sfoglia rettangolare refrigerata, circa 24 × 32 cm","brie con crosta edibile","salsa densa di cranberry o mirtilli rossi americani"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 dei 12 bocconcini","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g × peso di ogni ingrediente / 100, divisa per il numero di porzioni.","note":"Stima della formulazione: marche, porzioni reali e perdite di cottura cambiano i valori. Non è un’analisi di laboratorio."},"seo":{"title":"Bocconcini di sfoglia con brie e mirtilli rossi | Manual de Cocina","description":"Dodici cestini di sfoglia con brie fuso, salsa densa di cranberry e noci. Si cuociono in uno stampo da muffin standard per un antipasto dolce e salato.","image_alt":"Bocconcini di sfoglia con brie e mirtilli rossi","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"Si usano mirtilli blu?","a":"No. Servono cranberry rossi in salsa densa o confettura. I mirtilli blu danno un sapore diverso."},{"q":"Va tolta la crosta del brie?","a":"Non è necessario: è edibile e aiuta a contenere il formaggio. Toglila solo se preferisci."},{"q":"Posso omettere le noci?","a":"Sì. In caso di allergia eliminale e controlla tutte le etichette. La nutrizione pubblicata include le noci."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"cranberry-brie-puff-pastry-bites","public_path":"/ja/cranberry-brie-puff-pastry-bites","title":"ブリーとクランベリーのひと口パイ","excerpt":"パイ生地の小さなカップ12個に、溶けるブリー、濃いクランベリーソース、くるみを詰めます。標準サイズのマフィン型で焼く、甘みと塩味の前菜です。","summary":"パイ生地の小さなカップ12個に、溶けるブリー、濃いクランベリーソース、くるみを詰めます。標準サイズのマフィン型で焼く、甘みと塩味の前菜です。","notes":"赤いクランベリーの濃いソースを使い、生のブルーベリーとは区別します。24 × 32 cmの生地を8 cm角12枚に切れば切れ端が出ません。金属製の標準マフィン型12個分を使い、詰めすぎないでください。小麦、乳、くるみを含みます。残りは2時間以内に冷蔵し、2日以内にオーブンで温め直します。焼き時間は生地と型で調整します。","content_html":"<p>パイ生地の小さなカップ12個に、溶けるブリー、濃いクランベリーソース、くるみを詰めます。標準サイズのマフィン型で焼く、甘みと塩味の前菜です。</p><p>赤いクランベリーの濃いソースを使い、生のブルーベリーとは区別します。24 × 32 cmの生地を8 cm角12枚に切れば切れ端が出ません。金属製の標準マフィン型12個分を使い、詰めすぎないでください。小麦、乳、くるみを含みます。残りは2時間以内に冷蔵し、2日以内にオーブンで温め直します。焼き時間は生地と型で調整します。</p>","ingredients":[{"name":"冷蔵の長方形パイシート（約24 × 32 cm）","amount":"250","unit":"g"},{"name":"食べられる白い皮付きブリーチーズ","amount":"180","unit":"g"},{"name":"濃いクランベリーソース","amount":"120","unit":"g"},{"name":"殻を除いて刻んだくるみ","amount":"30","unit":"g"},{"name":"型用の油","amount":"5","unit":"g"},{"name":"細かく刻んだ生ローズマリーの葉","amount":"2","unit":"g"}],"steps":[{"title":"型を用意する","content":"上下加熱のオーブンを200 ℃に予熱します。金属製の標準マフィン型12個分に、油5 gを薄く塗ります。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"ブリーとクランベリーのひと口パイ: 型を用意する"},{"title":"正方形に切る","content":"冷たいパイ生地250 gを約24 × 32 cmに広げます。3 × 4の格子状に切り、8 cm角を12枚作ります。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"ブリーとクランベリーのひと口パイ: 正方形に切る"},{"title":"カップ状にする","content":"各くぼみに1枚ずつ入れ、底を軽く押さえます。四隅は上向きに残します。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"ブリーとクランベリーのひと口パイ: カップ状にする"},{"title":"ブリーを入れる","content":"ブリー180 gを約15 gずつ12等分し、各カップに1個入れます。食べられる皮は付いたままで構いません。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"ブリーとクランベリーのひと口パイ: ブリーを入れる"},{"title":"ソースを加える","content":"各チーズに濃いクランベリーソース10 gをのせます。型の上まで詰めないでください。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"ブリーとクランベリーのひと口パイ: ソースを加える"},{"title":"くるみを散らす","content":"刻んだくるみ30 gとローズマリーの葉2 gを12個に分けます。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"ブリーとクランベリーのひと口パイ: くるみを散らす"},{"title":"パイを焼く","content":"18〜20分、縁がきつね色になり底まで焼けるまで加熱します。上だけ色づきすぎる場合は最後にアルミホイルをふんわりかぶせます。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"ブリーとクランベリーのひと口パイ: パイを焼く"},{"title":"型から出して盛る","content":"5分置いてから小さなスプーンで取り出します。1人2個を温かい状態で出します。溶けたチーズの熱さに注意してください。","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"ブリーとクランベリーのひと口パイ: 型から出して盛る"}],"category":"前菜・おつまみ","course":"前菜","cuisine":"各国料理","difficulty":"簡単","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"ブリーとクランベリーのひと口パイ"}],"video_urls":[],"keywords":["ブリーとクランベリーのひと口パイ","冷蔵の長方形パイシート（約24 × 32 cm）","食べられる白い皮付きブリーチーズ","濃いクランベリーソース"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"全12個のうち2個","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"材料100 gあたりの栄養価×各使用重量÷100を合計し、人数で割って算出。","note":"配合からの推定値です。製品、実際の盛り付け量、加熱による損失で変わります。検査機関での分析値ではありません。"},"seo":{"title":"ブリーとクランベリーのひと口パイ | Manual de Cocina","description":"パイ生地の小さなカップ12個に、溶けるブリー、濃いクランベリーソース、くるみを詰めます。標準サイズのマフィン型で焼く、甘みと塩味の前菜です。","image_alt":"ブリーとクランベリーのひと口パイ","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"ブルーベリーを使うのですか？","a":"いいえ。赤いクランベリーの濃いソースやジャムを使います。ブルーベリーでは味が変わります。"},{"q":"ブリーの皮は取りますか？","a":"必須ではありません。食べられる皮で、チーズを包む役割もあります。好みで取り除けます。"},{"q":"くるみを抜いてもよいですか？","a":"はい。アレルギーがあれば省き、他の材料表示も確認します。掲載の栄養価はくるみ入りです。"}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"folhadinhos-brie-cranberry","public_path":"/pt/folhadinhos-brie-cranberry","title":"Folhadinhos de brie com cranberry e nozes","excerpt":"Doze cestinhas de massa folhada com brie derretido, molho espesso de cranberry e nozes. Um aperitivo agridoce assado em forma de muffins padrão.","summary":"Doze cestinhas de massa folhada com brie derretido, molho espesso de cranberry e nozes. Um aperitivo agridoce assado em forma de muffins padrão.","notes":"Use cranberry vermelho em molho espesso, não mirtilos azuis frescos. Uma folha de 24 × 32 cm rende doze quadrados de 8 cm sem sobras. Use forma metálica para doze muffins padrão e não encha até a borda. Contém trigo, leite e nozes. Refrigere as sobras em até 2 horas por no máximo 2 dias e reaqueça no forno. Ajuste o tempo à massa e à forma.","content_html":"<p>Doze cestinhas de massa folhada com brie derretido, molho espesso de cranberry e nozes. Um aperitivo agridoce assado em forma de muffins padrão.</p><p>Use cranberry vermelho em molho espesso, não mirtilos azuis frescos. Uma folha de 24 × 32 cm rende doze quadrados de 8 cm sem sobras. Use forma metálica para doze muffins padrão e não encha até a borda. Contém trigo, leite e nozes. Refrigere as sobras em até 2 horas por no máximo 2 dias e reaqueça no forno. Ajuste o tempo à massa e à forma.</p>","ingredients":[{"name":"massa folhada retangular refrigerada, cerca de 24 × 32 cm","amount":"250","unit":"g"},{"name":"queijo brie com casca comestível","amount":"180","unit":"g"},{"name":"molho espesso de cranberry vermelho","amount":"120","unit":"g"},{"name":"nozes sem casca picadas","amount":"30","unit":"g"},{"name":"óleo para untar","amount":"5","unit":"g"},{"name":"folhas de alecrim fresco picadas","amount":"2","unit":"g"}],"steps":[{"title":"Prepare a forma","content":"Preaqueça o forno a 200 °C, com calor superior e inferior. Unte levemente com 5 g de óleo uma forma metálica para doze muffins padrão.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-01.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Prepare a forma"},{"title":"Corte os quadrados","content":"Abra 250 g de massa fria em um retângulo de cerca de 24 × 32 cm. Corte uma grade de 3 × 4 para obter doze quadrados de 8 cm.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-02.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Corte os quadrados"},{"title":"Modele as cestinhas","content":"Acomode um quadrado em cada cavidade, pressionando de leve o fundo e deixando as pontas para cima.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-03.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Modele as cestinhas"},{"title":"Distribua o brie","content":"Corte 180 g de brie em doze pedaços iguais de cerca de 15 g. Coloque um em cada base; a casca comestível pode ficar.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-04.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Distribua o brie"},{"title":"Acrescente o cranberry","content":"Coloque 10 g de molho espesso de cranberry sobre cada pedaço de queijo, sem encher a cavidade até a borda.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-05.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Acrescente o cranberry"},{"title":"Finalize com nozes","content":"Divida 30 g de nozes picadas e 2 g de folhas de alecrim entre as doze cestinhas.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-06.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Finalize com nozes"},{"title":"Asse as cestinhas","content":"Asse por 18–20 minutos, até as bordas dourarem e o fundo cozinhar. Se dourar demais em cima, cubra frouxamente com alumínio no final.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-07.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Asse as cestinhas"},{"title":"Desenforme e sirva","content":"Espere 5 minutos e retire com uma colher pequena. Sirva dois folhadinhos mornos por pessoa; o queijo quente pode queimar.","image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/paso-08.webp","image_alt":"Folhadinhos de brie com cranberry e nozes: Desenforme e sirva"}],"category":"Entradas e aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":20,"total_time_minutes":45,"servings":6,"image_url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","gallery":[{"url":"/recetas/bocaditos-hojaldre-brie-arandanos/portada.webp","alt":"Folhadinhos de brie com cranberry e nozes"}],"video_urls":[],"keywords":["Folhadinhos de brie com cranberry e nozes","massa folhada retangular refrigerada, cerca de 24 × 32 cm","queijo brie com casca comestível","molho espesso de cranberry vermelho"],"nutrition":{"calories":323,"protein_g":9.4,"carbs_g":23.8,"fat_g":20.8,"saturated_fat_g":9.7,"fiber_g":1.4,"sodium_mg":319.9,"estimated":true,"serving_size":"2 dos 12 folhadinhos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g × peso de cada ingrediente / 100, dividida pelo número de porções.","note":"Estimativa pela formulação; marcas, porções reais e perdas no cozimento alteram os valores. Não é análise laboratorial."},"seo":{"title":"Folhadinhos de brie com cranberry e nozes | Manual de Cocina","description":"Doze cestinhas de massa folhada com brie derretido, molho espesso de cranberry e nozes. Um aperitivo agridoce assado em forma de muffins padrão.","image_alt":"Folhadinhos de brie com cranberry e nozes","image_variants":["/recetas/bocaditos-hojaldre-brie-arandanos/portada-1x1.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-4x3.webp","/recetas/bocaditos-hojaldre-brie-arandanos/portada-16x9.webp"],"faq":[{"q":"É feito com mirtilo azul?","a":"Não. Use cranberry vermelho em molho espesso ou geleia. O mirtilo azul dá outro sabor."},{"q":"Preciso retirar a casca do brie?","a":"Não. É comestível e ajuda a conter o queijo. Retire apenas se preferir."},{"q":"Posso retirar as nozes?","a":"Sim. Em caso de alergia, omita e confira todos os rótulos. A nutrição publicada inclui as nozes."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"es","slug":"datiles-rellenos-queso-tocineta","public_path":"/datiles-rellenos-queso-tocineta","title":"Dátiles rellenos de queso y envueltos en tocineta","excerpt":"Dátiles Medjool con queso de cabra cremoso, envueltos en tocineta fina y horneados hasta dorar. Una pequeña cantidad de miel picante al final acentúa el contraste dulce y salado.","summary":"Dátiles Medjool con queso de cabra cremoso, envueltos en tocineta fina y horneados hasta dorar. Una pequeña cantidad de miel picante al final acentúa el contraste dulce y salado.","notes":"Elige dátiles Medjool grandes y tocineta fina para que se cocine antes de que el relleno se salga. Retira todos los huesos y todos los palillos antes de comer. Usa queso de cabra pasteurizado. Contiene leche. Se calcula toda la tocineta y la miel; la grasa que queda en la bandeja no se descuenta, por lo que la estimación puede ser alta. Refrigera las sobras dentro de 2 horas, hasta 3 días, y recalienta hasta que estén bien calientes.","content_html":"<p>Dátiles Medjool con queso de cabra cremoso, envueltos en tocineta fina y horneados hasta dorar. Una pequeña cantidad de miel picante al final acentúa el contraste dulce y salado.</p><p>Elige dátiles Medjool grandes y tocineta fina para que se cocine antes de que el relleno se salga. Retira todos los huesos y todos los palillos antes de comer. Usa queso de cabra pasteurizado. Contiene leche. Se calcula toda la tocineta y la miel; la grasa que queda en la bandeja no se descuenta, por lo que la estimación puede ser alta. Refrigera las sobras dentro de 2 horas, hasta 3 días, y recalienta hasta que estén bien calientes.</p>","ingredients":[{"name":"dátiles Medjool grandes, peso sin hueso","amount":"288","unit":"g"},{"name":"queso de cabra cremoso pasteurizado","amount":"90","unit":"g"},{"name":"tocineta en 6 lonchas finas, cortadas por la mitad","amount":"120","unit":"g"},{"name":"miel","amount":"15","unit":"g"},{"name":"ají seco en hojuelas","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepara horno y bandeja","content":"Precalienta el horno a 200 °C, calor arriba y abajo. Pon una rejilla apta para horno sobre una bandeja con borde para recoger la grasa.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Prepara horno y bandeja"},{"title":"Abre los dátiles","content":"Haz una abertura longitudinal en 12 dátiles Medjool grandes y retira los huesos sin separar las mitades. Debes tener unos 288 g de fruta limpia.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Abre los dátiles"},{"title":"Rellena con queso","content":"Reparte 90 g de queso de cabra entre los 12 dátiles, unos 7–8 g por pieza. Cierra suavemente sin apretar el queso hacia fuera.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Rellena con queso"},{"title":"Envuelve con tocineta","content":"Corta 6 lonchas finas de tocineta por la mitad, obteniendo 12 tiras. Envuelve una alrededor de cada dátil.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Envuelve con tocineta"},{"title":"Sujeta y distribuye","content":"Asegura cada pieza con un palillo y colócala sobre la rejilla, con la unión hacia abajo y dejando espacio entre los dátiles.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Sujeta y distribuye"},{"title":"Hornea y gira","content":"Hornea 20–25 minutos y gira cuidadosamente a mitad de cocción, hasta que la tocineta esté dorada y completamente cocinada. Ajusta al grosor y sigue las instrucciones de cocción de su envase.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Hornea y gira"},{"title":"Añade miel picante","content":"Mezcla 15 g de miel con 0,5 g de ají seco. Deja reposar los dátiles 5 minutos fuera del horno y reparte una cantidad pequeña sobre cada uno.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Añade miel picante"},{"title":"Sirve los bocaditos","content":"Sirve 2 dátiles tibios por persona en una fuente crema. Advierte que contienen palillos y retíralos antes de comer; el relleno conserva calor.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Dátiles rellenos de queso y envueltos en tocineta: Sirve los bocaditos"}],"category":"Entrantes y aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Dátiles rellenos de queso y envueltos en tocineta"}],"video_urls":[],"keywords":["Dátiles rellenos de queso y envueltos en tocineta","dátiles Medjool grandes, peso sin hueso","queso de cabra cremoso pasteurizado","tocineta en 6 lonchas finas, cortadas por la mitad"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 de los 12 dátiles rellenos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g × peso de cada ingrediente / 100, dividida por las porciones.","note":"Estimación de la formulación; cambia según marcas, porción real y pérdidas de cocción. No es un análisis de laboratorio."},"seo":{"title":"Dátiles rellenos de queso y envueltos en tocineta | Manual de Cocina","description":"Dátiles Medjool con queso de cabra cremoso, envueltos en tocineta fina y horneados hasta dorar. Una pequeña cantidad de miel picante al final acentúa el contraste dulce y salado.","image_alt":"Dátiles rellenos de queso y envueltos en tocineta","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"¿Puedo prepararlos con anticipación?","a":"Sí: móntalos hasta 12 horas antes y mantenlos tapados en la nevera. Hornea al servir."},{"q":"¿Qué queso funciona?","a":"Un queso de cabra cremoso pasteurizado. El queso crema también funciona, pero cambia el sabor y la nutrición."},{"q":"¿Se puede omitir el picante?","a":"Sí. Usa solo la miel o sirve sin ella; la estimación publicada incluye los 15 g de miel y el ají."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"gefuellte-datteln-ziegenkaese-speck","public_path":"/de/gefuellte-datteln-ziegenkaese-speck","title":"Datteln mit Ziegenkäse im Speckmantel","excerpt":"Große Medjool-Datteln werden mit cremigem Ziegenkäse gefüllt und in dünnen Speck gewickelt. Nach dem Backen sorgt wenig Chili-Honig für einen süß-scharfen Abschluss.","summary":"Große Medjool-Datteln werden mit cremigem Ziegenkäse gefüllt und in dünnen Speck gewickelt. Nach dem Backen sorgt wenig Chili-Honig für einen süß-scharfen Abschluss.","notes":"Große Medjool-Datteln, dünnen Speck und pasteurisierten Ziegenkäse verwenden. Alle Kerne und vor dem Essen sämtliche Holzspießchen entfernen. Enthält Milch. Die Nährwerte rechnen Speck und Honig vollständig ein; ausgetretenes Fett wird nicht abgezogen. Die Schätzung kann deshalb hoch sein. Reste innerhalb von 2 Stunden kühlen, bis zu 3 Tage lagern und vollständig durcherhitzen.","content_html":"<p>Große Medjool-Datteln werden mit cremigem Ziegenkäse gefüllt und in dünnen Speck gewickelt. Nach dem Backen sorgt wenig Chili-Honig für einen süß-scharfen Abschluss.</p><p>Große Medjool-Datteln, dünnen Speck und pasteurisierten Ziegenkäse verwenden. Alle Kerne und vor dem Essen sämtliche Holzspießchen entfernen. Enthält Milch. Die Nährwerte rechnen Speck und Honig vollständig ein; ausgetretenes Fett wird nicht abgezogen. Die Schätzung kann deshalb hoch sein. Reste innerhalb von 2 Stunden kühlen, bis zu 3 Tage lagern und vollständig durcherhitzen.</p>","ingredients":[{"name":"große Medjool-Datteln, entsteint gewogen","amount":"288","unit":"g"},{"name":"cremiger pasteurisierter Ziegenkäse","amount":"90","unit":"g"},{"name":"dünner Frühstücksspeck, sechs halbierte Scheiben","amount":"120","unit":"g"},{"name":"Honig","amount":"15","unit":"g"},{"name":"getrocknete Chiliflocken","amount":"0.5","unit":"g"}],"steps":[{"title":"Blech vorbereiten","content":"Ofen auf 200 °C Ober-/Unterhitze vorheizen. Ein ofenfestes Gitter auf ein Blech mit Rand setzen, das Fett auffängt.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Blech vorbereiten"},{"title":"Datteln entsteinen","content":"Zwölf große Medjool-Datteln längs aufschneiden und die Kerne entfernen, ohne die Hälften zu trennen. Das Fruchtfleisch soll etwa 288 g wiegen.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Datteln entsteinen"},{"title":"Käse einfüllen","content":"90 g Ziegenkäse verteilen, etwa 7–8 g je Dattel. Vorsichtig schließen, ohne die Füllung herauszudrücken.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Käse einfüllen"},{"title":"Mit Speck umwickeln","content":"Sechs dünne Speckscheiben halbieren. Je einen der zwölf Streifen um eine Dattel wickeln.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Mit Speck umwickeln"},{"title":"Fixieren und verteilen","content":"Mit je einem Holzspießchen sichern und mit der Naht nach unten mit Abstand auf das Gitter legen.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Fixieren und verteilen"},{"title":"Backen und wenden","content":"20–25 Minuten backen und nach der Hälfte vorsichtig wenden, bis der Speck goldbraun und ganz durchgegart ist. Die Zeit an die Dicke und die Packungsangaben anpassen.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Backen und wenden"},{"title":"Chili-Honig zugeben","content":"15 g Honig mit 0,5 g Chiliflocken mischen. Datteln außerhalb des Ofens 5 Minuten ruhen lassen und sparsam beträufeln.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Chili-Honig zugeben"},{"title":"Häppchen servieren","content":"Je zwei lauwarme Datteln auf einer cremefarbenen Platte servieren. Auf die Spießchen hinweisen und sie vor dem Essen entfernen; die Füllung bleibt heiß.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Datteln mit Ziegenkäse im Speckmantel: Häppchen servieren"}],"category":"Vorspeisen","course":"Vorspeise","cuisine":"International","difficulty":"Einfach","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Datteln mit Ziegenkäse im Speckmantel"}],"video_urls":[],"keywords":["Datteln mit Ziegenkäse im Speckmantel","große Medjool-Datteln, entsteint gewogen","cremiger pasteurisierter Ziegenkäse","dünner Frühstücksspeck, sechs halbierte Scheiben"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 von 12 gefüllten Datteln","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Summe der Nährwerte je 100 g × Zutatengewicht / 100, geteilt durch die Portionenzahl.","note":"Schätzung aus der Rezeptur; Marke, tatsächliche Portion und Garverluste verändern die Werte. Keine Laboranalyse."},"seo":{"title":"Datteln mit Ziegenkäse im Speckmantel | Manual de Cocina","description":"Große Medjool-Datteln werden mit cremigem Ziegenkäse gefüllt und in dünnen Speck gewickelt. Nach dem Backen sorgt wenig Chili-Honig für einen süß-scharfen Abschluss.","image_alt":"Datteln mit Ziegenkäse im Speckmantel","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"Kann ich sie vorbereiten?","a":"Ja. Bis zu 12 Stunden vorher füllen, umwickeln und zugedeckt kühlen. Vor dem Servieren backen."},{"q":"Welcher Käse eignet sich?","a":"Cremiger pasteurisierter Ziegenkäse. Frischkäse geht auch, verändert aber Geschmack und Nährwerte."},{"q":"Geht es ohne Chili?","a":"Ja. Nur Honig verwenden oder den Guss ganz weglassen. Die angegebenen Nährwerte enthalten 15 g Honig und Chili."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"goat-cheese-bacon-wrapped-dates","public_path":"/en/goat-cheese-bacon-wrapped-dates","title":"Goat cheese stuffed dates wrapped in bacon","excerpt":"Large Medjool dates are filled with soft goat cheese and wrapped in thin bacon. Roast until golden, then finish with a restrained drizzle of chilli honey.","summary":"Large Medjool dates are filled with soft goat cheese and wrapped in thin bacon. Roast until golden, then finish with a restrained drizzle of chilli honey.","notes":"Use large Medjool dates, thin bacon and pasteurised goat cheese. Remove every stone and all cocktail sticks before eating. Contains milk. Nutrition includes all the bacon and honey without subtracting fat left in the tray, so the estimate may be high. Refrigerate leftovers within 2 hours for up to 3 days and reheat until hot throughout.","content_html":"<p>Large Medjool dates are filled with soft goat cheese and wrapped in thin bacon. Roast until golden, then finish with a restrained drizzle of chilli honey.</p><p>Use large Medjool dates, thin bacon and pasteurised goat cheese. Remove every stone and all cocktail sticks before eating. Contains milk. Nutrition includes all the bacon and honey without subtracting fat left in the tray, so the estimate may be high. Refrigerate leftovers within 2 hours for up to 3 days and reheat until hot throughout.</p>","ingredients":[{"name":"large Medjool dates, weighed after pitting","amount":"288","unit":"g"},{"name":"soft pasteurised goat cheese","amount":"90","unit":"g"},{"name":"thin bacon, six rashers cut in half","amount":"120","unit":"g"},{"name":"honey","amount":"15","unit":"g"},{"name":"dried chilli flakes","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepare the tray","content":"Heat the conventional oven to 200 °C. Put an oven-safe wire rack over a rimmed tray to catch the fat.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Prepare the tray"},{"title":"Pit the dates","content":"Slit twelve large Medjool dates lengthways and remove the stones without separating the halves. Aim for about 288 g pitted fruit.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Pit the dates"},{"title":"Add the cheese","content":"Divide 90 g goat cheese between the dates, about 7–8 g each. Close gently without squeezing out the filling.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Add the cheese"},{"title":"Wrap with bacon","content":"Cut six thin bacon rashers in half to make twelve strips. Wrap one around each date.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Wrap with bacon"},{"title":"Secure and arrange","content":"Secure each with a cocktail stick. Arrange on the rack seam-side down, with space between them.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Secure and arrange"},{"title":"Roast and turn","content":"Bake for 20–25 minutes, carefully turning halfway, until the bacon is golden and fully cooked. Adjust for thickness and follow the bacon packet cooking instructions.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Roast and turn"},{"title":"Add chilli honey","content":"Mix 15 g honey with 0.5 g dried chilli. Rest the dates for 5 minutes out of the oven, then drizzle a small amount over each.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Add chilli honey"},{"title":"Serve the bites","content":"Serve two warm dates per person on a cream platter. Warn guests about the sticks and remove them before eating; the filling retains heat.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Goat cheese stuffed dates wrapped in bacon: Serve the bites"}],"category":"Starters & appetizers","course":"Starter","cuisine":"International","difficulty":"Easy","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Goat cheese stuffed dates wrapped in bacon"}],"video_urls":[],"keywords":["Goat cheese stuffed dates wrapped in bacon","large Medjool dates, weighed after pitting","soft pasteurised goat cheese","thin bacon, six rashers cut in half"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 of 12 stuffed dates","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g × each ingredient weight / 100, divided by the number of servings.","note":"Recipe-based estimate; brands, actual portions and cooking losses affect the values. Not a laboratory analysis."},"seo":{"title":"Goat cheese stuffed dates wrapped in bacon | Manual de Cocina","description":"Large Medjool dates are filled with soft goat cheese and wrapped in thin bacon. Roast until golden, then finish with a restrained drizzle of chilli honey.","image_alt":"Goat cheese stuffed dates wrapped in bacon","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"Can I prepare them ahead?","a":"Yes. Assemble up to 12 hours ahead and keep covered in the fridge. Bake before serving."},{"q":"Which cheese works?","a":"Soft pasteurised goat cheese. Cream cheese also works but changes flavour and nutrition."},{"q":"Can I leave out the chilli?","a":"Yes. Use plain honey or omit the glaze. The published estimate includes 15 g honey and the chilli."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"dattes-farcies-chevre-bacon","public_path":"/fr/dattes-farcies-chevre-bacon","title":"Dattes farcies au chèvre et entourées de bacon","excerpt":"De grosses dattes Medjool cachent un peu de chèvre crémeux sous une fine tranche de bacon dorée au four. Une touche de miel pimenté souligne le contraste sucré-salé.","summary":"De grosses dattes Medjool cachent un peu de chèvre crémeux sous une fine tranche de bacon dorée au four. Une touche de miel pimenté souligne le contraste sucré-salé.","notes":"Choisissez de grosses Medjool, du bacon fin et du chèvre pasteurisé. Retirez tous les noyaux et tous les piques avant de manger. Contient du lait. Le calcul inclut tout le bacon et le miel, sans déduire la graisse restée sur la plaque ; l’estimation peut être élevée. Réfrigérez les restes sous 2 heures jusqu’à 3 jours et réchauffez à cœur.","content_html":"<p>De grosses dattes Medjool cachent un peu de chèvre crémeux sous une fine tranche de bacon dorée au four. Une touche de miel pimenté souligne le contraste sucré-salé.</p><p>Choisissez de grosses Medjool, du bacon fin et du chèvre pasteurisé. Retirez tous les noyaux et tous les piques avant de manger. Contient du lait. Le calcul inclut tout le bacon et le miel, sans déduire la graisse restée sur la plaque ; l’estimation peut être élevée. Réfrigérez les restes sous 2 heures jusqu’à 3 jours et réchauffez à cœur.</p>","ingredients":[{"name":"grosses dattes Medjool, poids dénoyauté","amount":"288","unit":"g"},{"name":"fromage de chèvre crémeux pasteurisé","amount":"90","unit":"g"},{"name":"bacon fin, six tranches coupées en deux","amount":"120","unit":"g"},{"name":"miel","amount":"15","unit":"g"},{"name":"piment séché en flocons","amount":"0.5","unit":"g"}],"steps":[{"title":"Préparer la plaque","content":"Préchauffez le four à 200 °C en chaleur statique. Posez une grille allant au four sur une plaque à rebord pour recueillir la graisse.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Préparer la plaque"},{"title":"Dénoyauter les dattes","content":"Fendez douze grosses Medjool dans la longueur et retirez les noyaux sans séparer les moitiés. Visez environ 288 g de fruit dénoyauté.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Dénoyauter les dattes"},{"title":"Farcir au chèvre","content":"Répartissez 90 g de chèvre, soit environ 7–8 g par datte. Refermez doucement sans faire sortir le fromage.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Farcir au chèvre"},{"title":"Envelopper de bacon","content":"Coupez six fines tranches de bacon en deux. Enroulez une des douze bandes autour de chaque datte.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Envelopper de bacon"},{"title":"Fixer et disposer","content":"Fixez chaque datte avec un pique en bois et posez sur la grille, jointure dessous, en les espaçant.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Fixer et disposer"},{"title":"Cuire et retourner","content":"Enfournez 20–25 minutes en retournant avec précaution à mi-cuisson, jusqu’à ce que le bacon soit doré et entièrement cuit. Adaptez à son épaisseur et suivez les indications du paquet.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Cuire et retourner"},{"title":"Ajouter le miel pimenté","content":"Mélangez 15 g de miel et 0,5 g de piment. Laissez les dattes reposer 5 minutes hors du four, puis nappez très légèrement.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Ajouter le miel pimenté"},{"title":"Servir les bouchées","content":"Servez deux dattes tièdes par personne sur un plat crème. Signalez les piques et retirez-les avant de manger ; la farce garde la chaleur.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Dattes farcies au chèvre et entourées de bacon: Servir les bouchées"}],"category":"Entrées et apéritifs","course":"Entrée","cuisine":"Internationale","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Dattes farcies au chèvre et entourées de bacon"}],"video_urls":[],"keywords":["Dattes farcies au chèvre et entourées de bacon","grosses dattes Medjool, poids dénoyauté","fromage de chèvre crémeux pasteurisé","bacon fin, six tranches coupées en deux"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 dattes farcies sur 12","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g × poids de chaque ingrédient / 100, divisée par le nombre de portions.","note":"Estimation selon la formulation ; les marques, les portions réelles et les pertes de cuisson modifient les valeurs. Pas une analyse de laboratoire."},"seo":{"title":"Dattes farcies au chèvre et entourées de bacon | Manual de Cocina","description":"De grosses dattes Medjool cachent un peu de chèvre crémeux sous une fine tranche de bacon dorée au four. Une touche de miel pimenté souligne le contraste sucré-salé.","image_alt":"Dattes farcies au chèvre et entourées de bacon","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"Peut-on les préparer à l’avance ?","a":"Oui. Assemblez-les jusqu’à 12 heures avant et conservez couvert au réfrigérateur. Faites cuire au moment de servir."},{"q":"Quel fromage choisir ?","a":"Un chèvre crémeux pasteurisé. Le fromage frais à tartiner convient aussi, mais modifie la saveur et la nutrition."},{"q":"Peut-on supprimer le piment ?","a":"Oui. Utilisez du miel seul ou servez sans nappage. Les valeurs publiées comprennent 15 g de miel et le piment."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"datteri-ripieni-caprino-bacon","public_path":"/it/datteri-ripieni-caprino-bacon","title":"Datteri ripieni di caprino avvolti nel bacon","excerpt":"Grandi datteri Medjool ripieni di caprino cremoso e avvolti in bacon sottile. Cuocili fino a doratura e completa con poco miele al peperoncino.","summary":"Grandi datteri Medjool ripieni di caprino cremoso e avvolti in bacon sottile. Cuocili fino a doratura e completa con poco miele al peperoncino.","notes":"Usa Medjool grandi, bacon sottile e caprino pastorizzato. Elimina tutti i noccioli e tutti gli stecchini prima di mangiare. Contiene latte. Il calcolo include tutto il bacon e il miele, senza sottrarre il grasso rimasto in teglia: la stima può risultare alta. Refrigera gli avanzi entro 2 ore per massimo 3 giorni e riscalda bene anche al centro.","content_html":"<p>Grandi datteri Medjool ripieni di caprino cremoso e avvolti in bacon sottile. Cuocili fino a doratura e completa con poco miele al peperoncino.</p><p>Usa Medjool grandi, bacon sottile e caprino pastorizzato. Elimina tutti i noccioli e tutti gli stecchini prima di mangiare. Contiene latte. Il calcolo include tutto il bacon e il miele, senza sottrarre il grasso rimasto in teglia: la stima può risultare alta. Refrigera gli avanzi entro 2 ore per massimo 3 giorni e riscalda bene anche al centro.</p>","ingredients":[{"name":"datteri Medjool grandi, peso senza nocciolo","amount":"288","unit":"g"},{"name":"caprino cremoso pastorizzato","amount":"90","unit":"g"},{"name":"bacon sottile, sei fette tagliate a metà","amount":"120","unit":"g"},{"name":"miele","amount":"15","unit":"g"},{"name":"peperoncino secco in fiocchi","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepara forno e teglia","content":"Scalda il forno statico a 200 °C. Metti una griglia adatta al forno sopra una teglia con bordo per raccogliere il grasso.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Prepara forno e teglia"},{"title":"Apri i datteri","content":"Incidi per il lungo dodici Medjool grandi e togli i noccioli senza separare le metà. Ottieni circa 288 g di frutta pulita.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Apri i datteri"},{"title":"Farcisci con il caprino","content":"Dividi 90 g di caprino tra i dodici datteri, circa 7–8 g ciascuno. Richiudi delicatamente senza far uscire il formaggio.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Farcisci con il caprino"},{"title":"Avvolgi nel bacon","content":"Taglia sei fette sottili di bacon a metà. Avvolgi una delle dodici strisce intorno a ogni dattero.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Avvolgi nel bacon"},{"title":"Fissa e disponi","content":"Ferma ciascuno con uno stecchino e metti sulla griglia con la giuntura sotto, lasciando spazio tra le porzioni.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Fissa e disponi"},{"title":"Cuoci e gira","content":"Inforna 20–25 minuti e gira con attenzione a metà cottura, finché il bacon è dorato e completamente cotto. Adatta al suo spessore e segui le istruzioni sulla confezione.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Cuoci e gira"},{"title":"Aggiungi miele piccante","content":"Mescola 15 g di miele con 0,5 g di peperoncino. Lascia riposare i datteri fuori dal forno 5 minuti e distribuisci poco composto su ciascuno.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Aggiungi miele piccante"},{"title":"Servi i bocconcini","content":"Servi due datteri tiepidi a persona su un piatto color crema. Segnala gli stecchini e toglili prima di mangiare: il ripieno trattiene calore.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Datteri ripieni di caprino avvolti nel bacon: Servi i bocconcini"}],"category":"Antipasti","course":"Antipasto","cuisine":"Internazionale","difficulty":"Facile","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Datteri ripieni di caprino avvolti nel bacon"}],"video_urls":[],"keywords":["Datteri ripieni di caprino avvolti nel bacon","datteri Medjool grandi, peso senza nocciolo","caprino cremoso pastorizzato","bacon sottile, sei fette tagliate a metà"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 dei 12 datteri ripieni","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g × peso di ogni ingrediente / 100, divisa per il numero di porzioni.","note":"Stima della formulazione: marche, porzioni reali e perdite di cottura cambiano i valori. Non è un’analisi di laboratorio."},"seo":{"title":"Datteri ripieni di caprino avvolti nel bacon | Manual de Cocina","description":"Grandi datteri Medjool ripieni di caprino cremoso e avvolti in bacon sottile. Cuocili fino a doratura e completa con poco miele al peperoncino.","image_alt":"Datteri ripieni di caprino avvolti nel bacon","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"Posso prepararli in anticipo?","a":"Sì. Farcisci e avvolgi fino a 12 ore prima, poi conserva coperto in frigo. Cuoci prima di servire."},{"q":"Quale formaggio funziona?","a":"Caprino cremoso pastorizzato. Anche il formaggio spalmabile funziona, ma cambia sapore e nutrizione."},{"q":"Posso omettere il peperoncino?","a":"Sì. Usa solo miele oppure niente glassa. La stima pubblicata include 15 g di miele e il peperoncino."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"goat-cheese-bacon-wrapped-dates","public_path":"/ja/goat-cheese-bacon-wrapped-dates","title":"ゴートチーズ入りデーツのベーコン巻き","excerpt":"大粒のメジュールデーツに柔らかいゴートチーズを詰め、薄切りベーコンで巻いて焼きます。仕上げの少量の唐辛子入りはちみつで甘みと塩味を引き立てます。","summary":"大粒のメジュールデーツに柔らかいゴートチーズを詰め、薄切りベーコンで巻いて焼きます。仕上げの少量の唐辛子入りはちみつで甘みと塩味を引き立てます。","notes":"大粒デーツ、薄切りベーコン、殺菌乳製のゴートチーズを選びます。種をすべて除き、食べる前につまようじもすべて外します。乳を含みます。栄養価は天板に落ちる脂を引かず、ベーコンとはちみつを全量計算しているため、高めの推定になる場合があります。残りは2時間以内に冷蔵し、3日以内に中心まで十分温め直して食べます。","content_html":"<p>大粒のメジュールデーツに柔らかいゴートチーズを詰め、薄切りベーコンで巻いて焼きます。仕上げの少量の唐辛子入りはちみつで甘みと塩味を引き立てます。</p><p>大粒デーツ、薄切りベーコン、殺菌乳製のゴートチーズを選びます。種をすべて除き、食べる前につまようじもすべて外します。乳を含みます。栄養価は天板に落ちる脂を引かず、ベーコンとはちみつを全量計算しているため、高めの推定になる場合があります。残りは2時間以内に冷蔵し、3日以内に中心まで十分温め直して食べます。</p>","ingredients":[{"name":"大粒のメジュールデーツ（種を除いた重量）","amount":"288","unit":"g"},{"name":"殺菌乳製の柔らかいゴートチーズ","amount":"90","unit":"g"},{"name":"薄切りベーコン6枚（半分に切る）","amount":"120","unit":"g"},{"name":"はちみつ","amount":"15","unit":"g"},{"name":"乾燥唐辛子フレーク","amount":"0.5","unit":"g"}],"steps":[{"title":"天板を用意する","content":"上下加熱のオーブンを200 ℃に予熱します。脂を受ける縁付き天板に、オーブン対応の網を置きます。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: 天板を用意する"},{"title":"デーツの種を除く","content":"大粒デーツ12個に縦の切り込みを入れ、半分に分離しないよう種を取ります。種なしの果肉約288 gが目安です。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: デーツの種を除く"},{"title":"チーズを詰める","content":"ゴートチーズ90 gを12個に分け、1個当たり約7〜8 gを詰めます。押し出さないよう優しく閉じます。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: チーズを詰める"},{"title":"ベーコンを巻く","content":"薄切りベーコン6枚を半分にして12本にします。各デーツに1本ずつ巻きます。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: ベーコンを巻く"},{"title":"固定して並べる","content":"つまようじで固定し、巻き終わりを下にして網に置きます。間隔を空けて並べます。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: 固定して並べる"},{"title":"返しながら焼く","content":"20〜25分、途中で注意して返し、ベーコンが色づき完全に加熱されるまで焼きます。厚さに合わせて時間を調整し、ベーコンの包装の加熱表示にも従います。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: 返しながら焼く"},{"title":"辛みのあるはちみつをかける","content":"はちみつ15 gと唐辛子0.5 gを混ぜます。デーツをオーブンから出して5分休ませ、各個に少量ずつかけます。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: 辛みのあるはちみつをかける"},{"title":"温かく盛り付ける","content":"1人2個をクリーム色の皿に盛ります。つまようじがあることを伝え、食べる前に外します。中のチーズは熱を保っています。","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"ゴートチーズ入りデーツのベーコン巻き: 温かく盛り付ける"}],"category":"前菜・おつまみ","course":"前菜","cuisine":"各国料理","difficulty":"簡単","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"ゴートチーズ入りデーツのベーコン巻き"}],"video_urls":[],"keywords":["ゴートチーズ入りデーツのベーコン巻き","大粒のメジュールデーツ（種を除いた重量）","殺菌乳製の柔らかいゴートチーズ","薄切りベーコン6枚（半分に切る）"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"全12個のうちチーズ入りデーツ2個","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"材料100 gあたりの栄養価×各使用重量÷100を合計し、人数で割って算出。","note":"配合からの推定値です。製品、実際の盛り付け量、加熱による損失で変わります。検査機関での分析値ではありません。"},"seo":{"title":"ゴートチーズ入りデーツのベーコン巻き | Manual de Cocina","description":"大粒のメジュールデーツに柔らかいゴートチーズを詰め、薄切りベーコンで巻いて焼きます。仕上げの少量の唐辛子入りはちみつで甘みと塩味を引き立てます。","image_alt":"ゴートチーズ入りデーツのベーコン巻き","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"先に準備しておけますか？","a":"はい。12時間前までに詰めて巻き、覆って冷蔵します。食べる前に焼きます。"},{"q":"どのチーズが使えますか？","a":"殺菌乳製の柔らかいゴートチーズです。クリームチーズでも作れますが、味と栄養価が変わります。"},{"q":"唐辛子を省いてもよいですか？","a":"はい。はちみつだけにするか、仕上げのソースを省けます。掲載の推定値ははちみつ15 gと唐辛子を含みます。"}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"tamaras-recheadas-queijo-cabra-bacon","public_path":"/pt/tamaras-recheadas-queijo-cabra-bacon","title":"Tâmaras recheadas com queijo de cabra e bacon","excerpt":"Tâmaras Medjool grandes recheadas com queijo de cabra cremoso e envolvidas em bacon fino. Asse até dourar e finalize com um fio discreto de mel com pimenta.","summary":"Tâmaras Medjool grandes recheadas com queijo de cabra cremoso e envolvidas em bacon fino. Asse até dourar e finalize com um fio discreto de mel com pimenta.","notes":"Escolha tâmaras Medjool grandes, bacon fino e queijo de cabra pasteurizado. Retire todos os caroços e todos os palitos antes de comer. Contém leite. O cálculo inclui todo o bacon e o mel, sem descontar a gordura que fica na assadeira; a estimativa pode ser alta. Refrigere as sobras em até 2 horas por no máximo 3 dias e reaqueça bem por dentro.","content_html":"<p>Tâmaras Medjool grandes recheadas com queijo de cabra cremoso e envolvidas em bacon fino. Asse até dourar e finalize com um fio discreto de mel com pimenta.</p><p>Escolha tâmaras Medjool grandes, bacon fino e queijo de cabra pasteurizado. Retire todos os caroços e todos os palitos antes de comer. Contém leite. O cálculo inclui todo o bacon e o mel, sem descontar a gordura que fica na assadeira; a estimativa pode ser alta. Refrigere as sobras em até 2 horas por no máximo 3 dias e reaqueça bem por dentro.</p>","ingredients":[{"name":"tâmaras Medjool grandes, peso sem caroço","amount":"288","unit":"g"},{"name":"queijo de cabra cremoso pasteurizado","amount":"90","unit":"g"},{"name":"bacon fino, seis fatias cortadas ao meio","amount":"120","unit":"g"},{"name":"mel","amount":"15","unit":"g"},{"name":"pimenta seca em flocos","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepare a assadeira","content":"Preaqueça o forno a 200 °C, com calor superior e inferior. Coloque uma grade própria para forno sobre uma assadeira com borda para recolher a gordura.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-01.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Prepare a assadeira"},{"title":"Abra as tâmaras","content":"Faça um corte longitudinal em doze tâmaras Medjool grandes e retire os caroços sem separar as metades. O peso limpo deve ser cerca de 288 g.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-02.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Abra as tâmaras"},{"title":"Recheie com queijo","content":"Divida 90 g de queijo de cabra entre as doze tâmaras, cerca de 7–8 g em cada. Feche com cuidado sem expulsar o recheio.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-03.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Recheie com queijo"},{"title":"Enrole no bacon","content":"Corte seis fatias finas de bacon ao meio, formando doze tiras. Enrole uma em cada tâmara.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-04.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Enrole no bacon"},{"title":"Prenda e distribua","content":"Prenda cada uma com um palito e coloque na grade com a emenda para baixo, deixando espaço entre elas.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-05.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Prenda e distribua"},{"title":"Asse e vire","content":"Asse por 20–25 minutos, virando com cuidado na metade, até o bacon dourar e cozinhar completamente. Ajuste à espessura e siga as instruções da embalagem do bacon.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-06.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Asse e vire"},{"title":"Acrescente mel com pimenta","content":"Misture 15 g de mel e 0,5 g de pimenta seca. Deixe as tâmaras descansarem fora do forno por 5 minutos e espalhe um pouco em cada uma.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-07.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Acrescente mel com pimenta"},{"title":"Sirva os aperitivos","content":"Sirva duas tâmaras mornas por pessoa em uma travessa creme. Avise sobre os palitos e retire antes de comer: o recheio retém calor.","image_url":"/recetas/datiles-rellenos-queso-tocineta/paso-08.webp","image_alt":"Tâmaras recheadas com queijo de cabra e bacon: Sirva os aperitivos"}],"category":"Entradas e aperitivos","course":"Entrada","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":20,"cook_time_minutes":25,"total_time_minutes":50,"servings":6,"image_url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","gallery":[{"url":"/recetas/datiles-rellenos-queso-tocineta/portada.webp","alt":"Tâmaras recheadas com queijo de cabra e bacon"}],"video_urls":[],"keywords":["Tâmaras recheadas com queijo de cabra e bacon","tâmaras Medjool grandes, peso sem caroço","queijo de cabra cremoso pasteurizado","bacon fino, seis fatias cortadas ao meio"],"nutrition":{"calories":259,"protein_g":6.4,"carbs_g":38.1,"fat_g":10.7,"fiber_g":3.2,"sugar_g":34.1,"sodium_mg":219.7,"estimated":true,"serving_size":"2 das 12 tâmaras recheadas","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g × peso de cada ingrediente / 100, dividida pelo número de porções.","note":"Estimativa pela formulação; marcas, porções reais e perdas no cozimento alteram os valores. Não é análise laboratorial."},"seo":{"title":"Tâmaras recheadas com queijo de cabra e bacon | Manual de Cocina","description":"Tâmaras Medjool grandes recheadas com queijo de cabra cremoso e envolvidas em bacon fino. Asse até dourar e finalize com um fio discreto de mel com pimenta.","image_alt":"Tâmaras recheadas com queijo de cabra e bacon","image_variants":["/recetas/datiles-rellenos-queso-tocineta/portada-1x1.webp","/recetas/datiles-rellenos-queso-tocineta/portada-4x3.webp","/recetas/datiles-rellenos-queso-tocineta/portada-16x9.webp"],"faq":[{"q":"Posso montar com antecedência?","a":"Sim. Monte até 12 horas antes e guarde coberto na geladeira. Asse ao servir."},{"q":"Qual queijo funciona?","a":"Queijo de cabra cremoso pasteurizado. Cream cheese também funciona, mas muda sabor e nutrição."},{"q":"Posso tirar a pimenta?","a":"Sim. Use apenas mel ou sirva sem cobertura. A estimativa publicada inclui 15 g de mel e a pimenta."}],"rest_time_minutes":5},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"es","slug":"tiramisu-turron-vasitos","public_path":"/tiramisu-turron-vasitos","title":"Tiramisú de turrón en vasitos, sin huevo crudo","excerpt":"Una versión navideña de tiramisú con crema de mascarpone y turrón blando de almendra, café y bizcochos de soletilla. Se monta en vasos y no lleva huevo crudo añadido.","summary":"Una versión navideña de tiramisú con crema de mascarpone y turrón blando de almendra, café y bizcochos de soletilla. Se monta en vasos y no lleva huevo crudo añadido.","notes":"Usa turrón blando de almendra tipo Jijona, no turrón duro. Los bizcochos y el turrón pueden contener huevo cocinado: esta receta no es apta para alérgicos al huevo. También contiene leche, almendra y trigo. Usa lácteos pasteurizados y conserva a 4 °C o menos, tapado, hasta 2 días. Puedes usar café descafeinado. La formulación no añade alcohol ni huevo crudo y está pendiente de prueba física en cocina.","content_html":"<p>Una versión navideña de tiramisú con crema de mascarpone y turrón blando de almendra, café y bizcochos de soletilla. Se monta en vasos y no lleva huevo crudo añadido.</p><p>Usa turrón blando de almendra tipo Jijona, no turrón duro. Los bizcochos y el turrón pueden contener huevo cocinado: esta receta no es apta para alérgicos al huevo. También contiene leche, almendra y trigo. Usa lácteos pasteurizados y conserva a 4 °C o menos, tapado, hasta 2 días. Puedes usar café descafeinado. La formulación no añade alcohol ni huevo crudo y está pendiente de prueba física en cocina.</p>","ingredients":[{"name":"turrón blando de almendra tipo Jijona","amount":"150","unit":"g"},{"name":"queso mascarpone","amount":"250","unit":"g"},{"name":"crema de leche para montar con 35 % de grasa, bien fría","amount":"200","unit":"g"},{"name":"bizcochos de soletilla o savoiardi","amount":"120","unit":"g"},{"name":"café preparado y frío, sin azúcar","amount":"180","unit":"ml"},{"name":"cacao puro sin azúcar","amount":"8","unit":"g"}],"steps":[{"title":"Prepara el café y los vasos","content":"Prepara 180 ml de café sin azúcar y deja enfriar por completo. Coloca 6 vasos de unos 200 ml sobre una bandeja.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Prepara el café y los vasos"},{"title":"Desmenuza el turrón","content":"Desmenuza finamente 150 g de turrón blando de almendra. Reserva 20 g para el acabado y pon los otros 130 g en un bol.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Desmenuza el turrón"},{"title":"Alisa la crema de turrón","content":"Añade 250 g de mascarpone al turrón del bol. Bate brevemente a velocidad baja hasta obtener una mezcla uniforme; no batas de más.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Alisa la crema de turrón"},{"title":"Incorpora la crema montada","content":"Monta 200 g de crema de leche bien fría a picos suaves y mézclala con el mascarpone y el turrón con movimientos envolventes.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Incorpora la crema montada"},{"title":"Forma la primera capa","content":"Parte los 120 g de bizcochos para adaptarlos a los vasos. Humedece rápidamente la mitad en el café frío y repártela como primera capa, sin empapar.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Forma la primera capa"},{"title":"Alterna las capas","content":"Cubre con la mitad de la crema. Repite con los bizcochos restantes humedecidos y termina con el resto de la crema. No es necesario consumir todo el café.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Alterna las capas"},{"title":"Refrigera para asentar","content":"Tapa los vasos sin tocar la crema y refrigera al menos 4 horas para que las capas se asienten.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Refrigera para asentar"},{"title":"Decora al servir","content":"Tamiza 8 g de cacao entre los 6 vasos y reparte los 20 g de turrón reservados. Sirve frío y mantén las porciones restantes refrigeradas.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo: Decora al servir"}],"category":"Postres","course":"Postre","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Tiramisú de turrón en vasitos, sin huevo crudo"}],"video_urls":[],"keywords":["Tiramisú de turrón en vasitos, sin huevo crudo","turrón blando de almendra tipo Jijona","queso mascarpone","crema de leche para montar con 35 % de grasa, bien fría"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 de los 6 vasitos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g × peso de cada ingrediente / 100, dividida por las porciones.","note":"Estimación de la formulación; cambia según marcas, porción real y pérdidas de cocción. No es un análisis de laboratorio."},"seo":{"title":"Tiramisú de turrón en vasitos, sin huevo crudo | Manual de Cocina","description":"Una versión navideña de tiramisú con crema de mascarpone y turrón blando de almendra, café y bizcochos de soletilla. Se monta en vasos y no lleva huevo crudo añadido.","image_alt":"Tiramisú de turrón en vasitos, sin huevo crudo","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"¿Esta receta no tiene huevo?","a":"No se añade huevo crudo, pero los bizcochos y algunos turrones sí llevan huevo cocinado. Revisa las etiquetas si hay alergia."},{"q":"¿Qué turrón se utiliza?","a":"Turrón blando de almendra tipo Jijona, que se desmenuza y mezcla con el mascarpone."},{"q":"¿Cuánto tiempo necesita en la nevera?","a":"Al menos 4 horas. Puedes prepararlo el día anterior y añadir el cacao y el turrón final justo antes de servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"turron-tiramisu-im-glas","public_path":"/de/turron-tiramisu-im-glas","title":"Turrón-Tiramisu im Glas ohne rohes Ei","excerpt":"Eine weihnachtliche Tiramisu-Variante mit weichem spanischem Mandel-Turrón, Mascarpone und Sahne. Mit kaffeefeuchten Löffelbiskuits in Gläser schichten und mindestens vier Stunden kühlen.","summary":"Eine weihnachtliche Tiramisu-Variante mit weichem spanischem Mandel-Turrón, Mascarpone und Sahne. Mit kaffeefeuchten Löffelbiskuits in Gläser schichten und mindestens vier Stunden kühlen.","notes":"Weichen Mandel-Turrón nach Jijona-Art verwenden, keinen harten weißen Nougat. Es wird kein rohes Ei zugegeben; Biskuits und Turrón können jedoch gegartes Ei enthalten. Nicht für Eierallergiker geeignet. Enthält Milch, Mandeln und Weizen. Pasteurisierte Milchprodukte verwenden, zugedeckt bei höchstens 4 °C bis zu 2 Tage kühlen. Entkoffeinierter Kaffee ist möglich. Die Rezeptur wurde nicht praktisch getestet.","content_html":"<p>Eine weihnachtliche Tiramisu-Variante mit weichem spanischem Mandel-Turrón, Mascarpone und Sahne. Mit kaffeefeuchten Löffelbiskuits in Gläser schichten und mindestens vier Stunden kühlen.</p><p>Weichen Mandel-Turrón nach Jijona-Art verwenden, keinen harten weißen Nougat. Es wird kein rohes Ei zugegeben; Biskuits und Turrón können jedoch gegartes Ei enthalten. Nicht für Eierallergiker geeignet. Enthält Milch, Mandeln und Weizen. Pasteurisierte Milchprodukte verwenden, zugedeckt bei höchstens 4 °C bis zu 2 Tage kühlen. Entkoffeinierter Kaffee ist möglich. Die Rezeptur wurde nicht praktisch getestet.</p>","ingredients":[{"name":"weicher spanischer Mandel-Turrón nach Jijona-Art","amount":"150","unit":"g"},{"name":"Mascarpone","amount":"250","unit":"g"},{"name":"kalte Schlagsahne mit 35 % Fett","amount":"200","unit":"g"},{"name":"Löffelbiskuits oder Savoiardi","amount":"120","unit":"g"},{"name":"kalter ungesüßter Kaffee","amount":"180","unit":"ml"},{"name":"ungesüßtes Kakaopulver","amount":"8","unit":"g"}],"steps":[{"title":"Kaffee und Gläser vorbereiten","content":"180 ml ungesüßten Kaffee kochen und vollständig abkühlen lassen. Sechs Gläser mit je etwa 200 ml auf ein Tablett stellen.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Kaffee und Gläser vorbereiten"},{"title":"Turrón zerbröseln","content":"150 g weichen Mandel-Turrón fein zerbröseln. 20 g für später zurückstellen, 130 g in eine Schüssel geben.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Turrón zerbröseln"},{"title":"Turróncreme rühren","content":"250 g Mascarpone zugeben und auf niedriger Stufe kurz gleichmäßig verrühren. Nicht zu lange schlagen.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Turróncreme rühren"},{"title":"Sahne unterheben","content":"200 g kalte Sahne bis zu weichen Spitzen schlagen und behutsam unter die Mascarpone-Turrón-Mischung heben.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Sahne unterheben"},{"title":"Erste Schicht legen","content":"120 g Biskuits passend brechen. Die Hälfte kurz in kalten Kaffee tauchen und in die Gläser legen, ohne sie durchzuweichen.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Erste Schicht legen"},{"title":"Schichten wiederholen","content":"Die Hälfte der Creme darauf verteilen. Übrige angefeuchtete Biskuits und restliche Creme einschichten. Nicht der gesamte Kaffee muss verbraucht werden.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Schichten wiederholen"},{"title":"Kalt stellen","content":"Gläser ohne Kontakt zur Creme abdecken und mindestens 4 Stunden kühlen.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Kalt stellen"},{"title":"Vor dem Servieren garnieren","content":"8 g Kakao über die sechs Gläser sieben und mit den übrigen 20 g Turrón bestreuen. Kalt servieren und verbleibende Portionen gekühlt halten.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei: Vor dem Servieren garnieren"}],"category":"Desserts","course":"Dessert","cuisine":"International","difficulty":"Einfach","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Turrón-Tiramisu im Glas ohne rohes Ei"}],"video_urls":[],"keywords":["Turrón-Tiramisu im Glas ohne rohes Ei","weicher spanischer Mandel-Turrón nach Jijona-Art","Mascarpone","kalte Schlagsahne mit 35 % Fett"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 von 6 Tiramisu-Gläsern","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Summe der Nährwerte je 100 g × Zutatengewicht / 100, geteilt durch die Portionenzahl.","note":"Schätzung aus der Rezeptur; Marke, tatsächliche Portion und Garverluste verändern die Werte. Keine Laboranalyse."},"seo":{"title":"Turrón-Tiramisu im Glas ohne rohes Ei | Manual de Cocina","description":"Eine weihnachtliche Tiramisu-Variante mit weichem spanischem Mandel-Turrón, Mascarpone und Sahne. Mit kaffeefeuchten Löffelbiskuits in Gläser schichten und mindestens vier Stunden kühlen.","image_alt":"Turrón-Tiramisu im Glas ohne rohes Ei","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"Ist das Dessert eifrei?","a":"Nein. Es wird zwar kein rohes Ei zugegeben, aber Biskuits und manche Turrónsorten enthalten gegartes Ei. Etiketten prüfen."},{"q":"Welcher Turrón passt?","a":"Weicher Mandel-Turrón nach Jijona-Art. Er lässt sich zerbröseln und mit Mascarpone vermischen."},{"q":"Wie lange muss es kühlen?","a":"Mindestens 4 Stunden. Am Vortag zubereiten und Kakao sowie die letzten Turrónbrösel erst vor dem Servieren zugeben."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"almond-turron-tiramisu-cups","public_path":"/en/almond-turron-tiramisu-cups","title":"Almond turrón tiramisu cups without raw egg","excerpt":"This Christmas variation layers coffee-dipped ladyfingers with mascarpone, whipped cream and soft Spanish almond turrón. Serve in glasses after at least four hours in the fridge.","summary":"This Christmas variation layers coffee-dipped ladyfingers with mascarpone, whipped cream and soft Spanish almond turrón. Serve in glasses after at least four hours in the fridge.","notes":"Use soft almond turrón, Jijona style, not hard white nougat. No raw egg is added, but the biscuits and turrón may contain cooked egg, so this is not egg-allergy safe. Contains milk, almonds and wheat. Use pasteurised dairy; refrigerate covered at 4 °C or below for up to 2 days. Decaffeinated coffee works. This editorial formulation has not been physically kitchen-tested.","content_html":"<p>This Christmas variation layers coffee-dipped ladyfingers with mascarpone, whipped cream and soft Spanish almond turrón. Serve in glasses after at least four hours in the fridge.</p><p>Use soft almond turrón, Jijona style, not hard white nougat. No raw egg is added, but the biscuits and turrón may contain cooked egg, so this is not egg-allergy safe. Contains milk, almonds and wheat. Use pasteurised dairy; refrigerate covered at 4 °C or below for up to 2 days. Decaffeinated coffee works. This editorial formulation has not been physically kitchen-tested.</p>","ingredients":[{"name":"soft Spanish almond turrón, Jijona style","amount":"150","unit":"g"},{"name":"mascarpone","amount":"250","unit":"g"},{"name":"cold whipping cream, 35% fat","amount":"200","unit":"g"},{"name":"ladyfinger biscuits or savoiardi","amount":"120","unit":"g"},{"name":"cold brewed coffee, unsweetened","amount":"180","unit":"ml"},{"name":"unsweetened cocoa powder","amount":"8","unit":"g"}],"steps":[{"title":"Prepare coffee and glasses","content":"Make 180 ml unsweetened coffee and let it cool completely. Arrange six 200 ml glasses on a tray.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Prepare coffee and glasses"},{"title":"Crumble the turrón","content":"Finely crumble 150 g soft almond turrón. Reserve 20 g for finishing and put the remaining 130 g in a bowl.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Crumble the turrón"},{"title":"Mix the nougat cream","content":"Add 250 g mascarpone to the bowl. Beat briefly on low speed until evenly mixed; do not overbeat.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Mix the nougat cream"},{"title":"Fold in whipped cream","content":"Whip 200 g cold cream to soft peaks and gently fold into the mascarpone and turrón.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Fold in whipped cream"},{"title":"Make the first layer","content":"Break 120 g ladyfingers to fit the glasses. Quickly dip half in the cold coffee and place in the bottoms without soaking.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Make the first layer"},{"title":"Alternate the layers","content":"Add half the cream. Repeat with the remaining dipped biscuits and finish with the remaining cream. You may not need all the coffee.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Alternate the layers"},{"title":"Chill to set","content":"Cover the glasses without touching the cream and refrigerate for at least 4 hours.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Chill to set"},{"title":"Finish before serving","content":"Sift 8 g cocoa over the six glasses and scatter over the reserved 20 g turrón. Serve cold and keep remaining portions refrigerated.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Almond turrón tiramisu cups without raw egg: Finish before serving"}],"category":"Desserts","course":"Dessert","cuisine":"International","difficulty":"Easy","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Almond turrón tiramisu cups without raw egg"}],"video_urls":[],"keywords":["Almond turrón tiramisu cups without raw egg","soft Spanish almond turrón, Jijona style","mascarpone","cold whipping cream, 35% fat"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 of 6 tiramisu cups","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g × each ingredient weight / 100, divided by the number of servings.","note":"Recipe-based estimate; brands, actual portions and cooking losses affect the values. Not a laboratory analysis."},"seo":{"title":"Almond turrón tiramisu cups without raw egg | Manual de Cocina","description":"This Christmas variation layers coffee-dipped ladyfingers with mascarpone, whipped cream and soft Spanish almond turrón. Serve in glasses after at least four hours in the fridge.","image_alt":"Almond turrón tiramisu cups without raw egg","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"Is this egg-free?","a":"No raw egg is added, but the biscuits and some turrón contain cooked egg. Check labels for allergies."},{"q":"Which turrón should I use?","a":"Soft Spanish almond turrón, Jijona style, which crumbles easily and blends into mascarpone."},{"q":"How long should it chill?","a":"At least 4 hours. Make it the day before and add the cocoa and final turrón just before serving."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"tiramisu-touron-amande-verrines","public_path":"/fr/tiramisu-touron-amande-verrines","title":"Tiramisu au touron en verrines, sans œuf cru","excerpt":"Une version de Noël au touron mou espagnol aux amandes, au mascarpone et à la crème fouettée. Alternez avec des biscuits imbibés de café puis réfrigérez au moins quatre heures.","summary":"Une version de Noël au touron mou espagnol aux amandes, au mascarpone et à la crème fouettée. Alternez avec des biscuits imbibés de café puis réfrigérez au moins quatre heures.","notes":"Choisissez du turrón mou aux amandes de type Jijona, pas du nougat dur. Aucun œuf cru n’est ajouté, mais les biscuits et le touron peuvent contenir de l’œuf cuit : ce dessert ne convient pas à l’allergie à l’œuf. Contient lait, amandes et blé. Utilisez des laitages pasteurisés et conservez couvert à 4 °C maximum jusqu’à 2 jours. Le café décaféiné convient. Formulation non testée physiquement en cuisine.","content_html":"<p>Une version de Noël au touron mou espagnol aux amandes, au mascarpone et à la crème fouettée. Alternez avec des biscuits imbibés de café puis réfrigérez au moins quatre heures.</p><p>Choisissez du turrón mou aux amandes de type Jijona, pas du nougat dur. Aucun œuf cru n’est ajouté, mais les biscuits et le touron peuvent contenir de l’œuf cuit : ce dessert ne convient pas à l’allergie à l’œuf. Contient lait, amandes et blé. Utilisez des laitages pasteurisés et conservez couvert à 4 °C maximum jusqu’à 2 jours. Le café décaféiné convient. Formulation non testée physiquement en cuisine.</p>","ingredients":[{"name":"touron mou espagnol aux amandes, type Jijona","amount":"150","unit":"g"},{"name":"mascarpone","amount":"250","unit":"g"},{"name":"crème liquide entière à 35 % de matière grasse, très froide","amount":"200","unit":"g"},{"name":"biscuits à la cuillère ou savoiardi","amount":"120","unit":"g"},{"name":"café préparé froid et non sucré","amount":"180","unit":"ml"},{"name":"cacao pur non sucré","amount":"8","unit":"g"}],"steps":[{"title":"Préparer café et verres","content":"Préparez 180 ml de café non sucré et laissez refroidir complètement. Posez six verres de 200 ml sur un plateau.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Préparer café et verres"},{"title":"Émietter le touron","content":"Émiettez finement 150 g de touron mou. Réservez 20 g pour la décoration et mettez les 130 g restants dans un bol.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Émietter le touron"},{"title":"Lisser la crème","content":"Ajoutez 250 g de mascarpone et fouettez brièvement à petite vitesse pour homogénéiser, sans trop battre.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Lisser la crème"},{"title":"Incorporer la crème montée","content":"Montez 200 g de crème très froide en pics souples et incorporez délicatement au mascarpone et au touron.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Incorporer la crème montée"},{"title":"Former la première couche","content":"Cassez 120 g de biscuits pour les adapter aux verres. Trempez rapidement la moitié dans le café froid et répartissez au fond sans détremper.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Former la première couche"},{"title":"Alterner les couches","content":"Ajoutez la moitié de la crème, puis les biscuits restants rapidement trempés et le reste de crème. Tout le café ne sera pas forcément utilisé.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Alterner les couches"},{"title":"Réfrigérer","content":"Couvrez sans toucher la crème et laissez au moins 4 heures au réfrigérateur.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Réfrigérer"},{"title":"Décorer au dernier moment","content":"Tamisez 8 g de cacao sur les six verres et ajoutez les 20 g de touron réservés. Servez froid et gardez les portions restantes réfrigérées.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Tiramisu au touron en verrines, sans œuf cru: Décorer au dernier moment"}],"category":"Desserts","course":"Dessert","cuisine":"Internationale","difficulty":"Facile","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Tiramisu au touron en verrines, sans œuf cru"}],"video_urls":[],"keywords":["Tiramisu au touron en verrines, sans œuf cru","touron mou espagnol aux amandes, type Jijona","mascarpone","crème liquide entière à 35 % de matière grasse, très froide"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 verrine de tiramisu sur 6","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g × poids de chaque ingrédient / 100, divisée par le nombre de portions.","note":"Estimation selon la formulation ; les marques, les portions réelles et les pertes de cuisson modifient les valeurs. Pas une analyse de laboratoire."},"seo":{"title":"Tiramisu au touron en verrines, sans œuf cru | Manual de Cocina","description":"Une version de Noël au touron mou espagnol aux amandes, au mascarpone et à la crème fouettée. Alternez avec des biscuits imbibés de café puis réfrigérez au moins quatre heures.","image_alt":"Tiramisu au touron en verrines, sans œuf cru","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"Est-ce un dessert sans œuf ?","a":"Aucun œuf cru n’est ajouté, mais les biscuits et certains tourons contiennent de l’œuf cuit. Vérifiez les étiquettes."},{"q":"Quel touron choisir ?","a":"Un touron mou espagnol aux amandes, type Jijona, qui s’émiette et se mélange au mascarpone."},{"q":"Combien de temps faut-il le refroidir ?","a":"Au moins 4 heures. Préparez-le la veille et ajoutez le cacao et le dernier touron juste avant de servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"tiramisu-turron-mandorle-bicchiere","public_path":"/it/tiramisu-turron-mandorle-bicchiere","title":"Tiramisù al turrón in bicchiere senza uova crude","excerpt":"Una variante natalizia con turrón spagnolo morbido alle mandorle, mascarpone e panna montata. Alterna la crema ai savoiardi al caffè e raffredda almeno quattro ore.","summary":"Una variante natalizia con turrón spagnolo morbido alle mandorle, mascarpone e panna montata. Alterna la crema ai savoiardi al caffè e raffredda almeno quattro ore.","notes":"Usa turrón spagnolo morbido alle mandorle tipo Jijona, non torrone duro. Non si aggiunge uovo crudo, ma savoiardi e turrón possono contenere uovo cotto: non è adatto all’allergia all’uovo. Contiene latte, mandorle e frumento. Scegli latticini pastorizzati e conserva coperto a massimo 4 °C per 2 giorni. Va bene anche il caffè decaffeinato. Formulazione non provata fisicamente in cucina.","content_html":"<p>Una variante natalizia con turrón spagnolo morbido alle mandorle, mascarpone e panna montata. Alterna la crema ai savoiardi al caffè e raffredda almeno quattro ore.</p><p>Usa turrón spagnolo morbido alle mandorle tipo Jijona, non torrone duro. Non si aggiunge uovo crudo, ma savoiardi e turrón possono contenere uovo cotto: non è adatto all’allergia all’uovo. Contiene latte, mandorle e frumento. Scegli latticini pastorizzati e conserva coperto a massimo 4 °C per 2 giorni. Va bene anche il caffè decaffeinato. Formulazione non provata fisicamente in cucina.</p>","ingredients":[{"name":"turrón spagnolo morbido alle mandorle, tipo Jijona","amount":"150","unit":"g"},{"name":"mascarpone","amount":"250","unit":"g"},{"name":"panna da montare al 35 % di grassi, fredda","amount":"200","unit":"g"},{"name":"savoiardi","amount":"120","unit":"g"},{"name":"caffè preparato freddo senza zucchero","amount":"180","unit":"ml"},{"name":"cacao amaro","amount":"8","unit":"g"}],"steps":[{"title":"Prepara caffè e bicchieri","content":"Prepara 180 ml di caffè senza zucchero e fallo raffreddare completamente. Disponi sei bicchieri da circa 200 ml su un vassoio.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Prepara caffè e bicchieri"},{"title":"Sbriciola il turrón","content":"Sbriciola finemente 150 g di turrón morbido. Tieni da parte 20 g e metti gli altri 130 g in una ciotola.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Sbriciola il turrón"},{"title":"Lavora la crema","content":"Aggiungi 250 g di mascarpone e mescola brevemente a bassa velocità fino a uniformare, senza lavorare troppo.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Lavora la crema"},{"title":"Incorpora la panna","content":"Monta 200 g di panna fredda a picchi morbidi e incorporala delicatamente al mascarpone e al turrón.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Incorpora la panna"},{"title":"Forma il primo strato","content":"Spezza 120 g di savoiardi per adattarli ai bicchieri. Bagna rapidamente metà dei biscotti nel caffè freddo e distribuiscili sul fondo senza inzupparli troppo.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Forma il primo strato"},{"title":"Alterna gli strati","content":"Aggiungi metà della crema. Ripeti con i savoiardi rimasti appena bagnati e termina con il resto della crema. Potrebbe avanzare del caffè.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Alterna gli strati"},{"title":"Lascia riposare in frigo","content":"Copri senza toccare la crema e refrigera per almeno 4 ore.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Lascia riposare in frigo"},{"title":"Decora e servi","content":"Setaccia 8 g di cacao sui sei bicchieri e aggiungi i 20 g di turrón tenuti da parte. Servi freddo e conserva in frigo le altre porzioni.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Tiramisù al turrón in bicchiere senza uova crude: Decora e servi"}],"category":"Dolci","course":"Dessert","cuisine":"Internazionale","difficulty":"Facile","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Tiramisù al turrón in bicchiere senza uova crude"}],"video_urls":[],"keywords":["Tiramisù al turrón in bicchiere senza uova crude","turrón spagnolo morbido alle mandorle, tipo Jijona","mascarpone","panna da montare al 35 % di grassi, fredda"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 dei 6 bicchierini di tiramisù","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g × peso di ogni ingrediente / 100, divisa per il numero di porzioni.","note":"Stima della formulazione: marche, porzioni reali e perdite di cottura cambiano i valori. Non è un’analisi di laboratorio."},"seo":{"title":"Tiramisù al turrón in bicchiere senza uova crude | Manual de Cocina","description":"Una variante natalizia con turrón spagnolo morbido alle mandorle, mascarpone e panna montata. Alterna la crema ai savoiardi al caffè e raffredda almeno quattro ore.","image_alt":"Tiramisù al turrón in bicchiere senza uova crude","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"È un dolce senza uova?","a":"Non si aggiungono uova crude, ma savoiardi e alcuni turrón contengono uovo cotto. Controlla le etichette."},{"q":"Quale turrón serve?","a":"Quello spagnolo morbido alle mandorle tipo Jijona, che si sbriciola e si amalgama al mascarpone."},{"q":"Quanto deve stare in frigo?","a":"Almeno 4 ore. Puoi prepararlo il giorno prima e aggiungere cacao e turrón finale al momento di servire."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"almond-turron-tiramisu-cups","public_path":"/ja/almond-turron-tiramisu-cups","title":"アーモンドトゥロンのカップティラミス・生卵不使用","excerpt":"柔らかいスペインのアーモンド菓子トゥロンを、マスカルポーネと生クリームに混ぜるクリスマス風ティラミスです。コーヒーを含ませたビスケットと重ね、4時間以上冷蔵します。","summary":"柔らかいスペインのアーモンド菓子トゥロンを、マスカルポーネと生クリームに混ぜるクリスマス風ティラミスです。コーヒーを含ませたビスケットと重ね、4時間以上冷蔵します。","notes":"ヒホナ風の柔らかいアーモンドトゥロンを使い、硬いヌガーとは区別します。生卵は加えませんが、ビスケットやトゥロンには加熱済み卵が含まれる場合があり、卵アレルギーには適しません。乳、アーモンド、小麦を含みます。殺菌済み乳製品を使い、覆って4 ℃以下で2日以内に保存します。デカフェでも作れます。実際の調理試験は行っていません。","content_html":"<p>柔らかいスペインのアーモンド菓子トゥロンを、マスカルポーネと生クリームに混ぜるクリスマス風ティラミスです。コーヒーを含ませたビスケットと重ね、4時間以上冷蔵します。</p><p>ヒホナ風の柔らかいアーモンドトゥロンを使い、硬いヌガーとは区別します。生卵は加えませんが、ビスケットやトゥロンには加熱済み卵が含まれる場合があり、卵アレルギーには適しません。乳、アーモンド、小麦を含みます。殺菌済み乳製品を使い、覆って4 ℃以下で2日以内に保存します。デカフェでも作れます。実際の調理試験は行っていません。</p>","ingredients":[{"name":"スペインの柔らかいアーモンドトゥロン（ヒホナ風）","amount":"150","unit":"g"},{"name":"マスカルポーネ","amount":"250","unit":"g"},{"name":"乳脂肪分35％のよく冷やした生クリーム","amount":"200","unit":"g"},{"name":"フィンガービスケットまたはサヴォイアルディ","amount":"120","unit":"g"},{"name":"抽出して冷ました無糖コーヒー","amount":"180","unit":"ml"},{"name":"無糖ココアパウダー","amount":"8","unit":"g"}],"steps":[{"title":"コーヒーとグラスを用意する","content":"無糖コーヒー180 mlを用意し、完全に冷まします。約200 mlのグラス6個をトレーに並べます。","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: コーヒーとグラスを用意する"},{"title":"トゥロンを崩す","content":"柔らかいトゥロン150 gを細かく崩します。仕上げ用に20 gを取り分け、残り130 gをボウルに入れます。","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: トゥロンを崩す"},{"title":"クリームを混ぜる","content":"マスカルポーネ250 gを加え、低速で短時間混ぜて均一にします。混ぜすぎないでください。","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: クリームを混ぜる"},{"title":"泡立てた生クリームを加える","content":"冷たい生クリーム200 gを柔らかい角が立つまで泡立て、マスカルポーネとトゥロンに優しく混ぜ込みます。","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: 泡立てた生クリームを加える"},{"title":"最初の層を作る","content":"ビスケット120 gをグラスに合う大きさに割ります。半量を冷たいコーヒーにさっとくぐらせ、浸しすぎず底に分けます。","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: 最初の層を作る"},{"title":"交互に重ねる","content":"クリームの半量をのせます。残りのビスケットをさっと湿らせて重ね、残りのクリームで仕上げます。コーヒーは全部使わなくても構いません。","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: 交互に重ねる"},{"title":"冷蔵庫でなじませる","content":"クリームに触れないよう覆い、4時間以上冷蔵して層をなじませます。","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: 冷蔵庫でなじませる"},{"title":"食べる直前に飾る","content":"ココア8 gを6個に分けてふるい、取り分けたトゥロン20 gを散らします。冷たくして出し、残りは冷蔵します。","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用: 食べる直前に飾る"}],"category":"デザート","course":"デザート","cuisine":"各国料理","difficulty":"簡単","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"アーモンドトゥロンのカップティラミス・生卵不使用"}],"video_urls":[],"keywords":["アーモンドトゥロンのカップティラミス・生卵不使用","スペインの柔らかいアーモンドトゥロン（ヒホナ風）","マスカルポーネ","乳脂肪分35％のよく冷やした生クリーム"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"全6個のうちティラミス1個","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"材料100 gあたりの栄養価×各使用重量÷100を合計し、人数で割って算出。","note":"配合からの推定値です。製品、実際の盛り付け量、加熱による損失で変わります。検査機関での分析値ではありません。"},"seo":{"title":"アーモンドトゥロンのカップティラミス・生卵不使用 | Manual de Cocina","description":"柔らかいスペインのアーモンド菓子トゥロンを、マスカルポーネと生クリームに混ぜるクリスマス風ティラミスです。コーヒーを含ませたビスケットと重ね、4時間以上冷蔵します。","image_alt":"アーモンドトゥロンのカップティラミス・生卵不使用","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"卵を一切含まないのですか？","a":"生卵は加えませんが、ビスケットや一部のトゥロンには加熱済み卵が入っています。表示を確認してください。"},{"q":"どのトゥロンを使いますか？","a":"ヒホナ風の柔らかいアーモンドトゥロンです。細かく崩せてマスカルポーネと混ざるものを使います。"},{"q":"冷やす時間はどれくらいですか？","a":"最低4時間です。前日に作り、ココアと仕上げのトゥロンは食べる直前に加えます。"}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"tiramisu-turron-amendoas-copinhos","public_path":"/pt/tiramisu-turron-amendoas-copinhos","title":"Tiramisù de turrón em copinhos, sem ovo cru","excerpt":"Uma versão natalina com turrón espanhol macio de amêndoas, mascarpone e creme batido. Monte camadas com biscoitos embebidos em café e leve à geladeira por pelo menos quatro horas.","summary":"Uma versão natalina com turrón espanhol macio de amêndoas, mascarpone e creme batido. Monte camadas com biscoitos embebidos em café e leve à geladeira por pelo menos quatro horas.","notes":"Use turrón espanhol macio de amêndoas tipo Jijona, não torrone duro. Não se adiciona ovo cru, mas os biscoitos e o turrón podem conter ovo cozido: não serve para alérgicos a ovo. Contém leite, amêndoas e trigo. Use laticínios pasteurizados e guarde coberto a 4 °C ou menos por até 2 dias. Pode usar café descafeinado. Formulação não testada fisicamente na cozinha.","content_html":"<p>Uma versão natalina com turrón espanhol macio de amêndoas, mascarpone e creme batido. Monte camadas com biscoitos embebidos em café e leve à geladeira por pelo menos quatro horas.</p><p>Use turrón espanhol macio de amêndoas tipo Jijona, não torrone duro. Não se adiciona ovo cru, mas os biscoitos e o turrón podem conter ovo cozido: não serve para alérgicos a ovo. Contém leite, amêndoas e trigo. Use laticínios pasteurizados e guarde coberto a 4 °C ou menos por até 2 dias. Pode usar café descafeinado. Formulação não testada fisicamente na cozinha.</p>","ingredients":[{"name":"turrón espanhol macio de amêndoas, tipo Jijona","amount":"150","unit":"g"},{"name":"queijo mascarpone","amount":"250","unit":"g"},{"name":"creme de leite fresco para bater com 35 % de gordura, gelado","amount":"200","unit":"g"},{"name":"biscoitos champagne ou savoiardi","amount":"120","unit":"g"},{"name":"café preparado frio sem açúcar","amount":"180","unit":"ml"},{"name":"cacau em pó puro sem açúcar","amount":"8","unit":"g"}],"steps":[{"title":"Prepare café e copos","content":"Prepare 180 ml de café sem açúcar e deixe esfriar completamente. Separe seis copos de cerca de 200 ml em uma bandeja.","image_url":"/recetas/tiramisu-turron-vasitos/paso-01.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Prepare café e copos"},{"title":"Esfarele o turrón","content":"Esfarele finamente 150 g de turrón macio. Reserve 20 g para decorar e coloque os outros 130 g em uma tigela.","image_url":"/recetas/tiramisu-turron-vasitos/paso-02.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Esfarele o turrón"},{"title":"Misture o creme","content":"Junte 250 g de mascarpone e bata rapidamente em velocidade baixa até homogeneizar, sem bater demais.","image_url":"/recetas/tiramisu-turron-vasitos/paso-03.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Misture o creme"},{"title":"Incorpore o creme batido","content":"Bata 200 g de creme de leite gelado até picos suaves e incorpore delicadamente ao mascarpone com turrón.","image_url":"/recetas/tiramisu-turron-vasitos/paso-04.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Incorpore o creme batido"},{"title":"Faça a primeira camada","content":"Quebre 120 g de biscoitos para caber nos copos. Umedeça rapidamente metade no café frio e distribua no fundo, sem encharcar.","image_url":"/recetas/tiramisu-turron-vasitos/paso-05.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Faça a primeira camada"},{"title":"Alterne as camadas","content":"Cubra com metade do creme. Repita com os biscoitos restantes umedecidos e finalize com o restante do creme. Não é preciso usar todo o café.","image_url":"/recetas/tiramisu-turron-vasitos/paso-06.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Alterne as camadas"},{"title":"Leve à geladeira","content":"Cubra sem encostar no creme e refrigere por pelo menos 4 horas para firmar as camadas.","image_url":"/recetas/tiramisu-turron-vasitos/paso-07.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Leve à geladeira"},{"title":"Decore ao servir","content":"Peneire 8 g de cacau sobre os seis copos e espalhe os 20 g de turrón reservados. Sirva gelado e mantenha as outras porções refrigeradas.","image_url":"/recetas/tiramisu-turron-vasitos/paso-08.webp","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru: Decore ao servir"}],"category":"Sobremesas","course":"Sobremesa","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":30,"cook_time_minutes":0,"total_time_minutes":270,"servings":6,"image_url":"/recetas/tiramisu-turron-vasitos/portada.webp","gallery":[{"url":"/recetas/tiramisu-turron-vasitos/portada.webp","alt":"Tiramisù de turrón em copinhos, sem ovo cru"}],"video_urls":[],"keywords":["Tiramisù de turrón em copinhos, sem ovo cru","turrón espanhol macio de amêndoas, tipo Jijona","queijo mascarpone","creme de leite fresco para bater com 35 % de gordura, gelado"],"nutrition":{"calories":491,"protein_g":9,"carbs_g":23.8,"fat_g":40.1,"saturated_fat_g":20.7,"sodium_mg":55.6,"estimated":true,"serving_size":"1 dos 6 copinhos de tiramisù","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g × peso de cada ingrediente / 100, dividida pelo número de porções.","note":"Estimativa pela formulação; marcas, porções reais e perdas no cozimento alteram os valores. Não é análise laboratorial."},"seo":{"title":"Tiramisù de turrón em copinhos, sem ovo cru | Manual de Cocina","description":"Uma versão natalina com turrón espanhol macio de amêndoas, mascarpone e creme batido. Monte camadas com biscoitos embebidos em café e leve à geladeira por pelo menos quatro horas.","image_alt":"Tiramisù de turrón em copinhos, sem ovo cru","image_variants":["/recetas/tiramisu-turron-vasitos/portada-1x1.webp","/recetas/tiramisu-turron-vasitos/portada-4x3.webp","/recetas/tiramisu-turron-vasitos/portada-16x9.webp"],"faq":[{"q":"É uma receita sem ovo?","a":"Não se acrescenta ovo cru, mas os biscoitos e alguns turróns contêm ovo cozido. Confira os rótulos."},{"q":"Qual turrón devo usar?","a":"O espanhol macio de amêndoas tipo Jijona, que se esfarela e mistura ao mascarpone."},{"q":"Quanto tempo precisa gelar?","a":"Pelo menos 4 horas. Prepare na véspera e acrescente o cacau e o turrón final pouco antes de servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"es","slug":"vasitos-cheesecake-pistacho-chocolate","public_path":"/vasitos-cheesecake-pistacho-chocolate","title":"Vasitos de cheesecake de pistacho y chocolate sin horno","excerpt":"Un postre en vasos con base de galleta, crema suave de queso y pistacho puro, y una capa fina de chocolate. Se prepara sin horno y se enfría antes de servir.","summary":"Un postre en vasos con base de galleta, crema suave de queso y pistacho puro, y una capa fina de chocolate. Se prepara sin horno y se enfría antes de servir.","notes":"Usa pasta de pistacho 100 % sin azúcar; una crema dulce cambia el dulzor y la firmeza. La textura es de postre para cuchara, no de tarta para desmoldar. Refrigera a 4 °C o menos durante 4 horas y conserva tapado hasta 2 días. Contiene leche, pistacho y gluten; revisa también la etiqueta del chocolate. No es una receta probada físicamente en cocina.","content_html":"<p>Un postre en vasos con base de galleta, crema suave de queso y pistacho puro, y una capa fina de chocolate. Se prepara sin horno y se enfría antes de servir.</p><p>Usa pasta de pistacho 100 % sin azúcar; una crema dulce cambia el dulzor y la firmeza. La textura es de postre para cuchara, no de tarta para desmoldar. Refrigera a 4 °C o menos durante 4 horas y conserva tapado hasta 2 días. Contiene leche, pistacho y gluten; revisa también la etiqueta del chocolate. No es una receta probada físicamente en cocina.</p>","ingredients":[{"name":"galletas tipo digestive","amount":"120","unit":"g"},{"name":"mantequilla sin sal","amount":"40","unit":"g"},{"name":"queso crema entero","amount":"300","unit":"g"},{"name":"pasta de pistacho 100 % sin azúcar","amount":"90","unit":"g"},{"name":"azúcar glas","amount":"45","unit":"g"},{"name":"crema de leche para montar con 35 % de grasa, bien fría","amount":"200","unit":"g"},{"name":"chocolate negro con 60–70 % de cacao","amount":"90","unit":"g"},{"name":"pistachos pelados sin sal, picados","amount":"20","unit":"g"}],"steps":[{"title":"Prepara los vasos","content":"Dispón 6 vasos de 200 ml. Tritura 120 g de galletas hasta obtener migas finas.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Prepara los vasos"},{"title":"Forma la base","content":"Derrite 40 g de mantequilla, mezcla con las migas y reparte entre los 6 vasos. Presiona suavemente con una cuchara y refrigera.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Forma la base"},{"title":"Mezcla queso y pistacho","content":"Bate brevemente 300 g de queso crema con 90 g de pasta de pistacho y 45 g de azúcar glas hasta alisar, sin calentar la mezcla.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Mezcla queso y pistacho"},{"title":"Monta parte de la crema","content":"Reserva 60 g de crema de leche para la cobertura. Bate los otros 140 g, bien fríos, hasta obtener picos suaves.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Monta parte de la crema"},{"title":"Rellena los vasos","content":"Incorpora la crema montada a la mezcla de pistacho en dos tandas con espátula. Reparte sobre las bases y alisa.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Rellena los vasos"},{"title":"Prepara el chocolate","content":"Calienta los 60 g de crema reservada hasta que humee suavemente, sin hervir fuerte. Vierte sobre 90 g de chocolate picado, espera 2 minutos y remueve hasta emulsionar.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Prepara el chocolate"},{"title":"Cubre y enfría","content":"Deja templar el chocolate hasta que esté fluido y apenas tibio. Distribuye una capa fina sobre los vasos. Tapa sin tocar la superficie y refrigera al menos 4 horas.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Cubre y enfría"},{"title":"Decora y sirve","content":"Reparte 20 g de pistachos picados sobre los 6 vasos y sirve frío. La base, la crema verde suave y el chocolate deben quedar visibles por el vidrio.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno: Decora y sirve"}],"category":"Postres","course":"Postre","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"Vasitos de cheesecake de pistacho y chocolate sin horno"}],"video_urls":[],"keywords":["Vasitos de cheesecake de pistacho y chocolate sin horno","galletas tipo digestive","mantequilla sin sal","queso crema entero"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 de 6 vasitos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g × peso de cada ingrediente / 100, dividida por las porciones.","note":"Estimación de la formulación; cambia según marcas, porción real y pérdidas de cocción. No es un análisis de laboratorio."},"seo":{"title":"Vasitos de cheesecake de pistacho y chocolate sin horno | Manual de Cocina","description":"Un postre en vasos con base de galleta, crema suave de queso y pistacho puro, y una capa fina de chocolate. Se prepara sin horno y se enfría antes de servir.","image_alt":"Vasitos de cheesecake de pistacho y chocolate sin horno","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar crema dulce de pistacho?","a":"La fórmula usa pasta 100 % pistacho. Una crema azucarada cambia la receta; no se sustituye gramo por gramo sin ajustar azúcar y textura."},{"q":"¿Necesita gelatina?","a":"No: se sirve en vaso y mantiene una textura cremosa para comer con cuchara."},{"q":"¿Se puede preparar el día anterior?","a":"Sí. Refrigera tapado a 4 °C o menos, hasta 2 días, y añade los pistachos al servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"de","slug":"pistazien-schoko-cheesecake-im-glas","public_path":"/de/pistazien-schoko-cheesecake-im-glas","title":"Pistazien-Schoko-Cheesecake im Glas ohne Backen","excerpt":"Keksboden, eine weiche Frischkäsecreme mit reinem Pistazienmus und eine dünne Schokoschicht ergeben sechs Desserts zum Löffeln. Vor dem Servieren mindestens vier Stunden kühlen.","summary":"Keksboden, eine weiche Frischkäsecreme mit reinem Pistazienmus und eine dünne Schokoschicht ergeben sechs Desserts zum Löffeln. Vor dem Servieren mindestens vier Stunden kühlen.","notes":"Ungesüßtes Mus aus 100 % Pistazien verwenden, keine süße Pistaziencreme. Das Dessert bleibt weich und wird nicht gestürzt. Zugedeckt bei höchstens 4 °C bis zu 2 Tage lagern. Enthält Milch, Pistazien und Weizen; auch die Schokoladenpackung prüfen. Die redaktionelle Rezeptur wurde nicht praktisch in der Küche getestet.","content_html":"<p>Keksboden, eine weiche Frischkäsecreme mit reinem Pistazienmus und eine dünne Schokoschicht ergeben sechs Desserts zum Löffeln. Vor dem Servieren mindestens vier Stunden kühlen.</p><p>Ungesüßtes Mus aus 100 % Pistazien verwenden, keine süße Pistaziencreme. Das Dessert bleibt weich und wird nicht gestürzt. Zugedeckt bei höchstens 4 °C bis zu 2 Tage lagern. Enthält Milch, Pistazien und Weizen; auch die Schokoladenpackung prüfen. Die redaktionelle Rezeptur wurde nicht praktisch in der Küche getestet.</p>","ingredients":[{"name":"Digestive-Kekse","amount":"120","unit":"g"},{"name":"ungesalzene Butter","amount":"40","unit":"g"},{"name":"Doppelrahmfrischkäse","amount":"300","unit":"g"},{"name":"ungesüßtes Pistazienmus aus 100 % Pistazien","amount":"90","unit":"g"},{"name":"Puderzucker","amount":"45","unit":"g"},{"name":"kalte Schlagsahne mit 35 % Fett","amount":"200","unit":"g"},{"name":"Zartbitterschokolade mit 60–70 % Kakao","amount":"90","unit":"g"},{"name":"gehackte ungesalzene Pistazienkerne","amount":"20","unit":"g"}],"steps":[{"title":"Gläser vorbereiten","content":"Sechs Gläser mit je 200 ml bereitstellen. 120 g Kekse fein zerbröseln.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Gläser vorbereiten"},{"title":"Böden formen","content":"40 g Butter schmelzen und mit den Bröseln mischen. Auf die Gläser verteilen, leicht andrücken und kalt stellen.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Böden formen"},{"title":"Pistaziencreme mischen","content":"300 g Frischkäse mit 90 g Pistazienmus und 45 g Puderzucker kurz glatt rühren. Die Masse nicht erwärmen.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Pistaziencreme mischen"},{"title":"Sahne schlagen","content":"60 g Sahne für den Guss zurückstellen. Die übrigen 140 g kalte Sahne bis zu weichen Spitzen schlagen.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Sahne schlagen"},{"title":"Gläser füllen","content":"Die geschlagene Sahne in zwei Portionen unter die Pistazienmasse heben. Auf den Keksböden verteilen und glatt streichen.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Gläser füllen"},{"title":"Schokolade schmelzen","content":"Die zurückgestellten 60 g Sahne sanft erhitzen, bis sie dampft. Über 90 g gehackte Schokolade gießen, 2 Minuten warten und glatt rühren.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Schokolade schmelzen"},{"title":"Überziehen und kühlen","content":"Den Guss lauwarm und noch flüssig werden lassen. Dünn auf die Gläser verteilen, ohne Oberflächenkontakt abdecken und mindestens 4 Stunden kühlen.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Überziehen und kühlen"},{"title":"Garnieren und servieren","content":"20 g gehackte Pistazien auf die sechs Gläser verteilen. Kalt servieren; Keksboden, hellgrüne Creme und Schokolade sollen sichtbar bleiben.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen: Garnieren und servieren"}],"category":"Desserts","course":"Dessert","cuisine":"International","difficulty":"Einfach","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen"}],"video_urls":[],"keywords":["Pistazien-Schoko-Cheesecake im Glas ohne Backen","Digestive-Kekse","ungesalzene Butter","Doppelrahmfrischkäse"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 von 6 Dessertgläsern","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Summe der Nährwerte je 100 g × Zutatengewicht / 100, geteilt durch die Portionenzahl.","note":"Schätzung aus der Rezeptur; Marke, tatsächliche Portion und Garverluste verändern die Werte. Keine Laboranalyse."},"seo":{"title":"Pistazien-Schoko-Cheesecake im Glas ohne Backen | Manual de Cocina","description":"Keksboden, eine weiche Frischkäsecreme mit reinem Pistazienmus und eine dünne Schokoschicht ergeben sechs Desserts zum Löffeln. Vor dem Servieren mindestens vier Stunden kühlen.","image_alt":"Pistazien-Schoko-Cheesecake im Glas ohne Backen","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"Geht auch süße Pistaziencreme?","a":"Das Rezept verwendet reines Pistazienmus. Eine gesüßte Creme verändert Süße und Festigkeit und ist kein direkter Ersatz."},{"q":"Braucht man Gelatine?","a":"Nein. Die weiche Creme wird direkt aus dem Glas gelöffelt."},{"q":"Kann ich das Dessert vorbereiten?","a":"Ja. Zugedeckt bei höchstens 4 °C bis zu 2 Tage kühlen und die Pistazien erst beim Servieren zugeben."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"en","slug":"pistachio-chocolate-cheesecake-cups","public_path":"/en/pistachio-chocolate-cheesecake-cups","title":"No-bake pistachio and chocolate cheesecake cups","excerpt":"Biscuit crumbs, a soft cream cheese and pure pistachio filling, and a thin chocolate topping make six spoonable desserts. Prepare them ahead and chill for at least four hours.","summary":"Biscuit crumbs, a soft cream cheese and pure pistachio filling, and a thin chocolate topping make six spoonable desserts. Prepare them ahead and chill for at least four hours.","notes":"Use unsweetened 100% pistachio paste, not sweet pistachio spread. These are soft desserts served in glasses, not a cheesecake for unmoulding. Refrigerate covered at 4 °C or below for up to 2 days. Contains milk, pistachios and wheat; check the chocolate label too. This editorial formulation has not been physically kitchen-tested.","content_html":"<p>Biscuit crumbs, a soft cream cheese and pure pistachio filling, and a thin chocolate topping make six spoonable desserts. Prepare them ahead and chill for at least four hours.</p><p>Use unsweetened 100% pistachio paste, not sweet pistachio spread. These are soft desserts served in glasses, not a cheesecake for unmoulding. Refrigerate covered at 4 °C or below for up to 2 days. Contains milk, pistachios and wheat; check the chocolate label too. This editorial formulation has not been physically kitchen-tested.</p>","ingredients":[{"name":"digestive biscuits","amount":"120","unit":"g"},{"name":"unsalted butter","amount":"40","unit":"g"},{"name":"full-fat cream cheese","amount":"300","unit":"g"},{"name":"unsweetened 100% pistachio paste","amount":"90","unit":"g"},{"name":"icing sugar","amount":"45","unit":"g"},{"name":"cold whipping cream, 35% fat","amount":"200","unit":"g"},{"name":"dark chocolate, 60–70% cocoa","amount":"90","unit":"g"},{"name":"chopped unsalted shelled pistachios","amount":"20","unit":"g"}],"steps":[{"title":"Prepare the glasses","content":"Set out six 200 ml glasses. Crush 120 g biscuits into fine crumbs.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Prepare the glasses"},{"title":"Make the bases","content":"Melt 40 g butter and mix with the crumbs. Divide between the glasses, press lightly with a spoon and refrigerate.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Make the bases"},{"title":"Mix cheese and pistachio","content":"Briefly beat 300 g cream cheese with 90 g pistachio paste and 45 g icing sugar until smooth. Do not warm the mixture.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Mix cheese and pistachio"},{"title":"Whip the cream","content":"Reserve 60 g cream for the topping. Whip the remaining 140 g cold cream to soft peaks.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Whip the cream"},{"title":"Fill the glasses","content":"Fold the whipped cream into the pistachio mixture in two additions. Spoon over the biscuit bases and level the tops.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Fill the glasses"},{"title":"Make the chocolate topping","content":"Heat the reserved 60 g cream until steaming gently. Pour over 90 g chopped chocolate, wait 2 minutes and stir until smooth.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Make the chocolate topping"},{"title":"Top and chill","content":"Let the chocolate cool until barely warm and still fluid. Spread a thin layer over each cup, cover without touching the surface and refrigerate for at least 4 hours.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Top and chill"},{"title":"Finish and serve","content":"Divide 20 g chopped pistachios between the six cups. Serve cold, with the biscuit, pale green filling and chocolate layers visible.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"No-bake pistachio and chocolate cheesecake cups: Finish and serve"}],"category":"Desserts","course":"Dessert","cuisine":"International","difficulty":"Easy","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"No-bake pistachio and chocolate cheesecake cups"}],"video_urls":[],"keywords":["No-bake pistachio and chocolate cheesecake cups","digestive biscuits","unsalted butter","full-fat cream cheese"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 of 6 dessert cups","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Sum of nutrients per 100 g × each ingredient weight / 100, divided by the number of servings.","note":"Recipe-based estimate; brands, actual portions and cooking losses affect the values. Not a laboratory analysis."},"seo":{"title":"No-bake pistachio and chocolate cheesecake cups | Manual de Cocina","description":"Biscuit crumbs, a soft cream cheese and pure pistachio filling, and a thin chocolate topping make six spoonable desserts. Prepare them ahead and chill for at least four hours.","image_alt":"No-bake pistachio and chocolate cheesecake cups","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"Can I use sweet pistachio spread?","a":"The recipe uses 100% pistachio paste. Sweet spread changes the sweetness and firmness and is not a direct replacement."},{"q":"Does it need gelatine?","a":"No. The filling stays soft and is eaten with a spoon from the glass."},{"q":"Can I make it ahead?","a":"Yes. Keep covered at 4 °C or below for up to 2 days and add the chopped pistachios just before serving."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"fr","slug":"verrines-cheesecake-pistache-chocolat","public_path":"/fr/verrines-cheesecake-pistache-chocolat","title":"Verrines de cheesecake pistache et chocolat sans cuisson","excerpt":"Une base biscuitée, une crème au fromage frais et à la pistache pure, puis une fine couche de chocolat. Six desserts à la cuillère à préparer au moins quatre heures avant de servir.","summary":"Une base biscuitée, une crème au fromage frais et à la pistache pure, puis une fine couche de chocolat. Six desserts à la cuillère à préparer au moins quatre heures avant de servir.","notes":"Choisissez une purée de pistache 100 % sans sucre, pas une pâte à tartiner sucrée. La crème reste souple et ne se démoule pas. Conservez les verrines couvertes à 4 °C maximum pendant 2 jours au plus. Contient lait, pistache et blé ; vérifiez aussi le chocolat. Cette formulation éditoriale n’a pas été testée physiquement en cuisine.","content_html":"<p>Une base biscuitée, une crème au fromage frais et à la pistache pure, puis une fine couche de chocolat. Six desserts à la cuillère à préparer au moins quatre heures avant de servir.</p><p>Choisissez une purée de pistache 100 % sans sucre, pas une pâte à tartiner sucrée. La crème reste souple et ne se démoule pas. Conservez les verrines couvertes à 4 °C maximum pendant 2 jours au plus. Contient lait, pistache et blé ; vérifiez aussi le chocolat. Cette formulation éditoriale n’a pas été testée physiquement en cuisine.</p>","ingredients":[{"name":"biscuits type digestive","amount":"120","unit":"g"},{"name":"beurre doux","amount":"40","unit":"g"},{"name":"fromage frais entier à tartiner","amount":"300","unit":"g"},{"name":"purée de pistache 100 % sans sucre","amount":"90","unit":"g"},{"name":"sucre glace","amount":"45","unit":"g"},{"name":"crème liquide entière à 35 % de matière grasse, très froide","amount":"200","unit":"g"},{"name":"chocolat noir à 60–70 % de cacao","amount":"90","unit":"g"},{"name":"pistaches décortiquées non salées et hachées","amount":"20","unit":"g"}],"steps":[{"title":"Préparer les verres","content":"Disposez six verres de 200 ml. Réduisez 120 g de biscuits en miettes fines.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Préparer les verres"},{"title":"Former les bases","content":"Faites fondre 40 g de beurre et mélangez avec les miettes. Répartissez dans les verres, tassez légèrement et réfrigérez.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Former les bases"},{"title":"Mélanger fromage et pistache","content":"Fouettez brièvement 300 g de fromage frais avec 90 g de purée de pistache et 45 g de sucre glace. Lissez sans réchauffer le mélange.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Mélanger fromage et pistache"},{"title":"Monter la crème","content":"Réservez 60 g de crème pour le chocolat. Fouettez les 140 g restants, bien froids, jusqu’à obtenir des pics souples.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Monter la crème"},{"title":"Garnir les verres","content":"Incorporez la crème fouettée au mélange pistache en deux fois, à la spatule. Répartissez sur les bases et lissez.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Garnir les verres"},{"title":"Préparer le chocolat","content":"Chauffez doucement les 60 g de crème réservée jusqu’à légère vapeur. Versez sur 90 g de chocolat haché, attendez 2 minutes puis mélangez pour émulsionner.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Préparer le chocolat"},{"title":"Couvrir et refroidir","content":"Laissez le chocolat devenir à peine tiède et encore fluide. Étalez une fine couche sur chaque verrine, couvrez sans toucher le dessus et réfrigérez au moins 4 heures.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Couvrir et refroidir"},{"title":"Décorer et servir","content":"Répartissez 20 g de pistaches hachées sur les six verrines. Servez froid, avec les couches de biscuit, crème vert pâle et chocolat visibles.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson: Décorer et servir"}],"category":"Desserts","course":"Dessert","cuisine":"Internationale","difficulty":"Facile","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"Verrines de cheesecake pistache et chocolat sans cuisson"}],"video_urls":[],"keywords":["Verrines de cheesecake pistache et chocolat sans cuisson","biscuits type digestive","beurre doux","fromage frais entier à tartiner"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 verrine sur 6","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g × poids de chaque ingrédient / 100, divisée par le nombre de portions.","note":"Estimation selon la formulation ; les marques, les portions réelles et les pertes de cuisson modifient les valeurs. Pas une analyse de laboratoire."},"seo":{"title":"Verrines de cheesecake pistache et chocolat sans cuisson | Manual de Cocina","description":"Une base biscuitée, une crème au fromage frais et à la pistache pure, puis une fine couche de chocolat. Six desserts à la cuillère à préparer au moins quatre heures avant de servir.","image_alt":"Verrines de cheesecake pistache et chocolat sans cuisson","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"Puis-je utiliser une crème de pistache sucrée ?","a":"La recette utilise de la pistache pure. Une pâte sucrée modifie le goût et la tenue et ne se remplace pas à poids égal."},{"q":"Faut-il de la gélatine ?","a":"Non. Le dessert reste crémeux et se mange à la cuillère dans son verre."},{"q":"Puis-je le préparer la veille ?","a":"Oui. Gardez-le couvert à 4 °C maximum jusqu’à 2 jours et ajoutez les pistaches au moment de servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"it","slug":"bicchierini-cheesecake-pistacchio-cioccolato","public_path":"/it/bicchierini-cheesecake-pistacchio-cioccolato","title":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura","excerpt":"Una base di biscotti, una morbida crema di formaggio e pistacchio puro e un sottile strato di cioccolato. Sei dessert al cucchiaio da far riposare in frigorifero almeno quattro ore.","summary":"Una base di biscotti, una morbida crema di formaggio e pistacchio puro e un sottile strato di cioccolato. Sei dessert al cucchiaio da far riposare in frigorifero almeno quattro ore.","notes":"Usa pasta di pistacchio pura al 100 % non zuccherata, non crema spalmabile dolce. Il dessert rimane morbido e non va sformato. Conservalo coperto a 4 °C o meno per massimo 2 giorni. Contiene latte, pistacchi e frumento; controlla anche il cioccolato. Questa formulazione editoriale non è stata provata fisicamente in cucina.","content_html":"<p>Una base di biscotti, una morbida crema di formaggio e pistacchio puro e un sottile strato di cioccolato. Sei dessert al cucchiaio da far riposare in frigorifero almeno quattro ore.</p><p>Usa pasta di pistacchio pura al 100 % non zuccherata, non crema spalmabile dolce. Il dessert rimane morbido e non va sformato. Conservalo coperto a 4 °C o meno per massimo 2 giorni. Contiene latte, pistacchi e frumento; controlla anche il cioccolato. Questa formulazione editoriale non è stata provata fisicamente in cucina.</p>","ingredients":[{"name":"biscotti tipo digestive","amount":"120","unit":"g"},{"name":"burro non salato","amount":"40","unit":"g"},{"name":"formaggio fresco spalmabile intero","amount":"300","unit":"g"},{"name":"pasta di pistacchio 100 % senza zucchero","amount":"90","unit":"g"},{"name":"zucchero a velo","amount":"45","unit":"g"},{"name":"panna fresca da montare al 35 % di grassi, fredda","amount":"200","unit":"g"},{"name":"cioccolato fondente al 60–70 % di cacao","amount":"90","unit":"g"},{"name":"pistacchi sgusciati non salati, tritati","amount":"20","unit":"g"}],"steps":[{"title":"Prepara i bicchieri","content":"Disponi sei bicchieri da 200 ml. Riduci 120 g di biscotti in briciole fini.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Prepara i bicchieri"},{"title":"Forma le basi","content":"Sciogli 40 g di burro e mescolalo alle briciole. Dividi nei bicchieri, premi leggermente con un cucchiaio e metti in frigo.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Forma le basi"},{"title":"Mescola formaggio e pistacchio","content":"Lavora brevemente 300 g di formaggio con 90 g di pasta di pistacchio e 45 g di zucchero a velo, senza scaldare il composto.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Mescola formaggio e pistacchio"},{"title":"Monta la panna","content":"Tieni da parte 60 g di panna per la copertura. Monta i restanti 140 g ben freddi fino a ottenere picchi morbidi.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Monta la panna"},{"title":"Riempi i bicchieri","content":"Incorpora la panna montata al pistacchio in due volte con una spatola. Distribuisci sulle basi e livella.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Riempi i bicchieri"},{"title":"Prepara il cioccolato","content":"Scalda delicatamente i 60 g di panna fino a farla fumare appena. Versala su 90 g di cioccolato tritato, attendi 2 minuti e mescola fino a emulsionare.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Prepara il cioccolato"},{"title":"Copri e raffredda","content":"Lascia intiepidire il cioccolato mantenendolo fluido. Stendine uno strato sottile sui bicchieri, copri senza toccare la superficie e refrigera almeno 4 ore.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Copri e raffredda"},{"title":"Decora e servi","content":"Dividi 20 g di pistacchi tritati sui sei dessert e servi freddo, lasciando visibili gli strati di biscotto, crema verde chiaro e cioccolato.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura: Decora e servi"}],"category":"Dolci","course":"Dessert","cuisine":"Internazionale","difficulty":"Facile","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura"}],"video_urls":[],"keywords":["Cheesecake al pistacchio e cioccolato in bicchiere senza cottura","biscotti tipo digestive","burro non salato","formaggio fresco spalmabile intero"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 dei 6 bicchierini","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g × peso di ogni ingrediente / 100, divisa per il numero di porzioni.","note":"Stima della formulazione: marche, porzioni reali e perdite di cottura cambiano i valori. Non è un’analisi di laboratorio."},"seo":{"title":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura | Manual de Cocina","description":"Una base di biscotti, una morbida crema di formaggio e pistacchio puro e un sottile strato di cioccolato. Sei dessert al cucchiaio da far riposare in frigorifero almeno quattro ore.","image_alt":"Cheesecake al pistacchio e cioccolato in bicchiere senza cottura","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"Posso usare crema dolce al pistacchio?","a":"La ricetta usa pistacchio puro. La crema zuccherata cambia dolcezza e consistenza e non è un sostituto diretto."},{"q":"Serve gelatina?","a":"No. È un dessert morbido da mangiare al cucchiaio nel bicchiere."},{"q":"Si prepara il giorno prima?","a":"Sì. Conservalo coperto a massimo 4 °C fino a 2 giorni e aggiungi i pistacchi al momento di servire."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"ja","slug":"pistachio-chocolate-cheesecake-cups","public_path":"/ja/pistachio-chocolate-cheesecake-cups","title":"焼かないピスタチオとチョコのカップチーズケーキ","excerpt":"ビスケットの土台に、純粋なピスタチオペースト入りのクリームチーズを重ね、薄いチョコレートの層で仕上げます。6個分のスプーンで食べるデザートです。冷蔵庫で4時間以上冷やします。","summary":"ビスケットの土台に、純粋なピスタチオペースト入りのクリームチーズを重ね、薄いチョコレートの層で仕上げます。6個分のスプーンで食べるデザートです。冷蔵庫で4時間以上冷やします。","notes":"無糖のピスタチオ100％ペーストを使用します。加糖スプレッドとは別物です。柔らかいカップデザートなので型抜きしません。ふたをして4 ℃以下で冷蔵し、2日以内に食べてください。乳、ピスタチオ、小麦を含みます。チョコレートの表示も確認してください。この配合は編集上の提案で、実際の調理試験は行っていません。","content_html":"<p>ビスケットの土台に、純粋なピスタチオペースト入りのクリームチーズを重ね、薄いチョコレートの層で仕上げます。6個分のスプーンで食べるデザートです。冷蔵庫で4時間以上冷やします。</p><p>無糖のピスタチオ100％ペーストを使用します。加糖スプレッドとは別物です。柔らかいカップデザートなので型抜きしません。ふたをして4 ℃以下で冷蔵し、2日以内に食べてください。乳、ピスタチオ、小麦を含みます。チョコレートの表示も確認してください。この配合は編集上の提案で、実際の調理試験は行っていません。</p>","ingredients":[{"name":"ダイジェスティブビスケット","amount":"120","unit":"g"},{"name":"食塩不使用バター","amount":"40","unit":"g"},{"name":"全脂肪クリームチーズ","amount":"300","unit":"g"},{"name":"無糖ピスタチオ100％ペースト","amount":"90","unit":"g"},{"name":"粉砂糖","amount":"45","unit":"g"},{"name":"乳脂肪分35％のよく冷やした生クリーム","amount":"200","unit":"g"},{"name":"カカオ分60〜70％のダークチョコレート","amount":"90","unit":"g"},{"name":"殻を除いた無塩ピスタチオ（刻む）","amount":"20","unit":"g"}],"steps":[{"title":"グラスを用意する","content":"200 mlのグラスを6個用意します。ビスケット120 gを細かく砕きます。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: グラスを用意する"},{"title":"土台を作る","content":"バター40 gを溶かしてビスケットと混ぜます。6個のグラスに分け、スプーンで軽く押さえて冷蔵します。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: 土台を作る"},{"title":"チーズとピスタチオを混ぜる","content":"クリームチーズ300 g、ピスタチオペースト90 g、粉砂糖45 gを短時間混ぜて滑らかにします。温まるほど混ぜ続けないでください。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: チーズとピスタチオを混ぜる"},{"title":"生クリームを泡立てる","content":"生クリーム60 gをチョコ用に取り分けます。残り140 gを冷たい状態で、柔らかい角が立つまで泡立てます。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: 生クリームを泡立てる"},{"title":"グラスに詰める","content":"泡立てた生クリームを2回に分けてピスタチオの生地にへらで混ぜ込みます。土台の上に分け入れ、表面をならします。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: グラスに詰める"},{"title":"チョコを準備する","content":"取り分けた生クリーム60 gを穏やかに湯気が出るまで温めます。刻んだチョコ90 gに注いで2分待ち、滑らかに乳化するまで混ぜます。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: チョコを準備する"},{"title":"表面を覆って冷やす","content":"チョコを、流動性があり、わずかに温かい程度まで冷まします。各カップに薄く広げ、表面に触れないよう覆い、4時間以上冷蔵します。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: 表面を覆って冷やす"},{"title":"飾って食べる","content":"刻んだピスタチオ20 gを6個に分けてのせます。ビスケット、淡い緑色のクリーム、チョコの層が見える状態で冷たくして出します。","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ: 飾って食べる"}],"category":"デザート","course":"デザート","cuisine":"各国料理","difficulty":"簡単","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"焼かないピスタチオとチョコのカップチーズケーキ"}],"video_urls":[],"keywords":["焼かないピスタチオとチョコのカップチーズケーキ","ダイジェスティブビスケット","食塩不使用バター","全脂肪クリームチーズ"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"全6個のうち1個","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"材料100 gあたりの栄養価×各使用重量÷100を合計し、人数で割って算出。","note":"配合からの推定値です。製品、実際の盛り付け量、加熱による損失で変わります。検査機関での分析値ではありません。"},"seo":{"title":"焼かないピスタチオとチョコのカップチーズケーキ | Manual de Cocina","description":"ビスケットの土台に、純粋なピスタチオペースト入りのクリームチーズを重ね、薄いチョコレートの層で仕上げます。6個分のスプーンで食べるデザートです。冷蔵庫で4時間以上冷やします。","image_alt":"焼かないピスタチオとチョコのカップチーズケーキ","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"加糖ピスタチオスプレッドでも作れますか？","a":"この配合は無糖の純粋なペースト用です。加糖品では甘さと固さが変わるため、同量での単純な置き換えはできません。"},{"q":"ゼラチンは必要ですか？","a":"不要です。柔らかいクリームをグラスからスプーンで食べます。"},{"q":"前日に作れますか？","a":"はい。覆って4 ℃以下で2日以内を目安に保存し、刻んだピスタチオは食べる直前に加えます。"}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null},{"language":"pt","slug":"copinhos-cheesecake-pistache-chocolate","public_path":"/pt/copinhos-cheesecake-pistache-chocolate","title":"Cheesecake de pistache e chocolate no copinho, sem forno","excerpt":"Base de biscoito, creme macio de queijo com pasta pura de pistache e uma camada fina de chocolate. São seis sobremesas de colher que precisam de pelo menos quatro horas de geladeira.","summary":"Base de biscoito, creme macio de queijo com pasta pura de pistache e uma camada fina de chocolate. São seis sobremesas de colher que precisam de pelo menos quatro horas de geladeira.","notes":"Use pasta 100 % pistache sem açúcar, não creme doce de pistache. A sobremesa fica cremosa e não deve ser desenformada. Guarde coberta a 4 °C ou menos por até 2 dias. Contém leite, pistache e trigo; confira também o rótulo do chocolate. Esta formulação editorial não foi testada fisicamente na cozinha.","content_html":"<p>Base de biscoito, creme macio de queijo com pasta pura de pistache e uma camada fina de chocolate. São seis sobremesas de colher que precisam de pelo menos quatro horas de geladeira.</p><p>Use pasta 100 % pistache sem açúcar, não creme doce de pistache. A sobremesa fica cremosa e não deve ser desenformada. Guarde coberta a 4 °C ou menos por até 2 dias. Contém leite, pistache e trigo; confira também o rótulo do chocolate. Esta formulação editorial não foi testada fisicamente na cozinha.</p>","ingredients":[{"name":"biscoitos tipo digestive","amount":"120","unit":"g"},{"name":"manteiga sem sal","amount":"40","unit":"g"},{"name":"cream cheese integral","amount":"300","unit":"g"},{"name":"pasta 100 % pistache sem açúcar","amount":"90","unit":"g"},{"name":"açúcar de confeiteiro","amount":"45","unit":"g"},{"name":"creme de leite fresco para bater com 35 % de gordura, bem gelado","amount":"200","unit":"g"},{"name":"chocolate amargo com 60–70 % de cacau","amount":"90","unit":"g"},{"name":"pistaches sem casca e sem sal, picados","amount":"20","unit":"g"}],"steps":[{"title":"Prepare os copos","content":"Separe seis copos de 200 ml. Triture 120 g de biscoitos até obter uma farofa fina.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-01.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Prepare os copos"},{"title":"Faça as bases","content":"Derreta 40 g de manteiga e misture à farofa. Divida entre os copos, pressione levemente com uma colher e leve à geladeira.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-02.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Faça as bases"},{"title":"Misture queijo e pistache","content":"Bata rapidamente 300 g de cream cheese com 90 g de pasta de pistache e 45 g de açúcar de confeiteiro, até alisar sem aquecer a mistura.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-03.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Misture queijo e pistache"},{"title":"Bata parte do creme","content":"Reserve 60 g de creme de leite para a cobertura. Bata os 140 g restantes, bem gelados, até formar picos suaves.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-04.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Bata parte do creme"},{"title":"Recheie os copos","content":"Incorpore o creme batido à mistura de pistache em duas adições, com espátula. Divida sobre as bases e alise.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-05.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Recheie os copos"},{"title":"Prepare o chocolate","content":"Aqueça os 60 g de creme reservados até soltar vapor suave. Despeje sobre 90 g de chocolate picado, espere 2 minutos e mexa até emulsionar.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-06.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Prepare o chocolate"},{"title":"Cubra e gele","content":"Deixe o chocolate ficar apenas morno, ainda fluido. Espalhe uma camada fina em cada copo, cubra sem tocar a superfície e gele por pelo menos 4 horas.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-07.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Cubra e gele"},{"title":"Decore e sirva","content":"Divida 20 g de pistaches picados entre os seis copos. Sirva gelado, com as camadas de biscoito, creme verde-claro e chocolate visíveis.","image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/paso-08.webp","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno: Decore e sirva"}],"category":"Sobremesas","course":"Sobremesa","cuisine":"Internacional","difficulty":"Fácil","prep_time_minutes":30,"cook_time_minutes":5,"total_time_minutes":275,"servings":6,"image_url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","gallery":[{"url":"/recetas/vasitos-cheesecake-pistacho-chocolate/portada.webp","alt":"Cheesecake de pistache e chocolate no copinho, sem forno"}],"video_urls":[],"keywords":["Cheesecake de pistache e chocolate no copinho, sem forno","biscoitos tipo digestive","manteiga sem sal","cream cheese integral"],"nutrition":{"calories":654,"protein_g":10.3,"carbs_g":37,"fat_g":53,"saturated_fat_g":27.5,"fiber_g":3.8,"sugar_g":20.1,"sodium_mg":273.5,"estimated":true,"serving_size":"1 dos 6 copinhos","source":"USDA FoodData Central SR Legacy + manufacturer reference labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g × peso de cada ingrediente / 100, dividida pelo número de porções.","note":"Estimativa pela formulação; marcas, porções reais e perdas no cozimento alteram os valores. Não é análise laboratorial."},"seo":{"title":"Cheesecake de pistache e chocolate no copinho, sem forno | Manual de Cocina","description":"Base de biscoito, creme macio de queijo com pasta pura de pistache e uma camada fina de chocolate. São seis sobremesas de colher que precisam de pelo menos quatro horas de geladeira.","image_alt":"Cheesecake de pistache e chocolate no copinho, sem forno","image_variants":["/recetas/vasitos-cheesecake-pistacho-chocolate/portada-1x1.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-4x3.webp","/recetas/vasitos-cheesecake-pistacho-chocolate/portada-16x9.webp"],"faq":[{"q":"Posso usar creme doce de pistache?","a":"A receita usa pasta pura. O creme açucarado muda a doçura e a firmeza e não é uma substituição direta."},{"q":"Precisa de gelatina?","a":"Não. A textura é cremosa e a sobremesa é servida de colher no copo."},{"q":"Posso preparar na véspera?","a":"Sim. Guarde coberto a no máximo 4 °C por até 2 dias e acrescente os pistaches ao servir."}],"rest_time_minutes":240},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null}]$payload$::jsonb;
aliases jsonb := $aliases$[{"alias":"mantequilla sin sal","slug":"mantequilla"},{"alias":"crema de leche para montar con 35 % de grasa, bien fría","slug":"crema-de-leche"},{"alias":"mozzarella de baja humedad rallada","slug":"queso-mozzarella"},{"alias":"parmesano rallado","slug":"queso-parmesano"},{"alias":"huevo batido para pincelar","slug":"huevo"},{"alias":"aceite para engrasar el molde","slug":"aceite-vegetal"},{"alias":"crema de leche para montar con 35 % de grasa, bien fría","slug":"crema-de-leche"},{"alias":"cacao puro sin azúcar","slug":"cacao-en-polvo"},{"alias":"tocineta en 6 lonchas finas, cortadas por la mitad","slug":"tocineta"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; n int:=0;
BEGIN
IF jsonb_array_length(j)<>35 THEN RAISE EXCEPTION 'Expected 35 records'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe collision; no rows created'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(j) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'URL collision; no rows created'; END IF;
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias)
 SELECT i.id,a->>'alias',lower(trim(a->>'alias')) FROM public.ingredients i
 WHERE i.slug=a->>'slug' AND i.status='canonical' AND i.searchable
 AND NOT EXISTS(SELECT 1 FROM public.ingredient_aliases ia WHERE ia.ingredient_id=i.id AND lower(trim(ia.alias))=lower(trim(a->>'alias')));
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;
 ELSE
  IF source_id IS NULL THEN RAISE EXCEPTION 'Spanish source required'; END IF;
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo WHERE id=made.id;
 n:=n+1;
END LOOP;
IF n<>35 THEN RAISE EXCEPTION 'Expected 35 creates'; END IF;
END $stage$;
